import { answered, ask as askFace, calm, hold, isWaiting, react, release, stage as stageFace, tick, type Face, type Mood } from './mood'

const PANE = 'avatar7'
const FACE = 'face'
const FRAME_MS = 66
// The weather around the face moves at a third of the face's pace.
const AMBIENT_FRAMES = 3
// The HD weather: a loop of HD_LOOP pictures, one per ambient step.
const HD_LOOP = 12
const HD_STEP_S = (AMBIENT_FRAMES * FRAME_MS) / 1000
const AMB_LEFT = 'amb-left'
const AMB_RIGHT = 'amb-right'
const AMB_BAND = 'amb-band'
// The scene rises behind the face to its middle and runs this many rows past
// the text.
const SCENE_OVERFLOW_ROWS = 6
const DEFAULT = 'shodan'
const AVATARS = ['shodan', 'hal', 'glados', 'ada', 'duck7', 'pod042', 'kaneda', 'commis', 'fox', 'adjutant', 'morte', 'pda', 'lain', 'tachikoma', 'nova']

const MIN_SIZE = 16
// A refusal acted in a scene shakes the portrait this much of a real one.
const SCENE_GLITCH = 0.4

// Rows kept under the face for the line, which may wrap once, the pending
// approval, the buttons and the two rules between them.
const TEXT_ROWS = 6

// The engine redraws on a change of width, never on a change of height alone:
// the clock asks for a render this often so the face follows both.
const REFIT_FRAMES = 15

// The face's side in pixels for a pane body: as wide as the body, as tall as
// the body leaves (two pixels per row, a few rows kept for the text), even,
// never past the baked portrait.
const fit = (columns: number, rows: number): number => {
  const side = Math.min(W, columns, Math.max(MIN_SIZE / 2, rows - TEXT_ROWS) * 2)
  return Math.max(MIN_SIZE, side - (side % 2))
}

const line = atom({ plugin: 'avatar7', key: 'line' } as const, { text: '', at: 0 })
const isMuted = atom({ plugin: 'avatar7', key: 'isMuted' } as const, false)
// SAPI volume, 0 to 100, kept across sessions in $.store.
const volume = atom({ plugin: 'avatar7', key: 'volume' } as const, 100)
const VOLUME_STEP = 10
// The avatar on duty, by its id: other mods read it (jukebox7 picks its music).
const onDuty = atom({ plugin: 'avatar7', key: 'avatar' } as const, '')
// The on-duty persona's color, read by jukebox7 to light its pane alike.
const tint = atom({ plugin: 'avatar7', key: 'color' } as const, '')
// The on-duty persona's station, read by jukebox7 for its avatar's pick.
const station = atom({ plugin: 'avatar7', key: 'station' } as const, { name: '', artists: [] } as Station)
// The mods that asked for a voice, by plugin name: each publishes its own
// `announce` key, and the avatar hears the write.
// True while a line is heard: jukebox7 lowers its music meanwhile.
const isVoicing = atom({ plugin: 'avatar7', key: 'isVoicing' } as const, false)
const announcers = atom({ plugin: 'avatar7', key: 'announcers' } as const, {} as Record<string, Announce>)

// An ask the mode may settle alone (auto mode): the face waits at once, the
// avatar speaks only if the permission prompt is still up after ~2 s.
const ASK_FRAMES = 30
// The longest a wait keeps the face: 15 minutes.
const WAIT_CAP_FRAMES = Math.round((15 * 60_000) / FRAME_MS)

// How long a line about a call through mesh7 waits for mesh7-pane's verdict:
// its poll runs every 1.5 s.
const SAY_WAIT_FRAMES = 27


// The remote voice's engine calls (relay.ts holds the rest): declared here,
// in this file, as the engine follows $ into nothing imported.
async function relayOpen($: Engine, r: Relay): Promise<void> {
  r.session = await $.session.id()
  r.isSsh = (await $.process.run(['sh', '-c', 'printf %s "$SSH_CONNECTION"'])).stdout.trim() !== ''
}

async function relayGive($: Engine, r: Relay): Promise<void> {
  await $.process.run(releaseArgv(r.session))
  r.isHeld = false
}

// Each frame: who holds the relay, now and then; the face, when held and
// changed; the page's presses.
function relayTick($: Engine, r: Relay, frame: number, host: RelayHost): void {
  if (r.session === '') return
  if (frame % CHECK_FRAMES === 0) {
    void (async () => {
      // After a /clear the process goes on under a new id, with no
      // session.start: a relay held by force follows it there.
      const id = await $.session.id()
      if (id !== r.session) {
        r.session = id
        if (r.isForced) await $.process.run(takeArgv(r.session))
      }
      r.isHeld = (await $.process.run(heldArgv(r.session))).stdout.trim() === 'up'
      if (!r.isHeld) r.mirrored = ''
    })().catch(err => $.ui.log(`avatar7: the relay check failed: ${String(err)}`, { to: 'debug' }))
  }
  if (r.isHeld && !r.isMirroring && frame % MIRROR_FRAMES === 0) {
    const face = host.face()
    if (face !== undefined) {
      r.isMirroring = true
      void (async () => {
        const json = JSON.stringify(await face)
        if (json !== r.mirrored) await $.process.run(mirrorArgv(r.session), { stdin: json })
        r.mirrored = json
      })()
        .catch(err => $.ui.log(`avatar7: the relay's mirror failed: ${String(err)}`, { to: 'debug' }))
        .finally(() => {
          r.isMirroring = false
        })
    }
  }
  if (r.isHeld && !r.isDraining && frame % DRAIN_FRAMES === 0) {
    r.isDraining = true
    void (async () => {
      const out = await $.process.run(drainArgv())
      for (const each of out.stdout.split('\n')) {
        const press = parseRemote(each)
        if (press !== undefined) await host.press(press)
      }
    })()
      .catch(err => $.ui.log(`avatar7: the page's commands failed: ${String(err)}`, { to: 'debug' }))
      .finally(() => {
        r.isDraining = false
      })
  }
}

// /avatar remote on: start the relay when no service runs it, and hold it.
async function relayOn($: Engine, r: Relay): Promise<string> {
  if ((await $.process.run(aliveArgv())).stdout.trim() !== 'up') {
    await $.process.run(startArgv($.plugin.root))
    await $.clock.sleep(1500)
  }
  r.isForced = true
  await $.process.run(takeArgv(r.session))
  const ip = await $.process.run(['sh', '-c', 'tailscale ip -4 | head -1'])
  return `The voice leaves this machine: open http://${ip.stdout.trim()}:8797/ on the other one and click listen.`
}

// /avatar remote off: give the relay back; the relay itself keeps running.
async function relayOff($: Engine, r: Relay): Promise<string> {
  r.isForced = false
  await relayGive($, r)
  return 'The voice comes back to this machine.'
}

async function relayFollow($: Engine, r: Relay, origin: string): Promise<void> {
  const move = follows(r, origin)
  if (move === 'take') await $.process.run(takeArgv(r.session))
  else if (move === 'give') await relayGive($, r)
  // Written whole again at the next mirror: a release left `{}` behind.
  if (r.session !== '') r.mirrored = ''
}

async function relayEnd($: Engine, r: Relay, reason: string): Promise<void> {
  if (givesOnEnd(r, reason)) await relayGive($, r)
}

// A persona's faces (draw.ts): the portrait, and the optional frames baked
// beside it (tools/bake.py --frame): mouth open for speaking, a frown for a
// refusal.
// Whether this terminal draws pictures for the Image element: kitty and
// Ghostty implement the Unicode placeholders it needs, WezTerm and Windows
// Terminal do not. AVATAR7_HD=0 keeps the half blocks anyway. Set at
// session start, before the faces load.
let isHdTerminal = false
export const drawsPictures = (env: string): boolean => {
  const [term = '', program = '', flag = ''] = env.split('|')
  if (flag === '0') return false
  return term === 'xterm-kitty' || term === 'xterm-ghostty' || program === 'ghostty'
}

// The faces and scene tools/bake_hd.py baked for this persona, null when
// they are not there (a fresh clone: they are derived, kept out of git).
async function loadHd($: Engine, dir: string): Promise<Hd | null> {
  const bytes = async (name: string): Promise<Uint8Array | null> => {
    try {
      return Uint8Array.fromBase64((await $.fs.read(`${dir}/${name}`, { as: 'bytes' })).base64)
    } catch {
      return null
    }
  }
  let meta: { size?: number; sceneWidth?: number; sceneHeight?: number }
  try {
    meta = JSON.parse(String(await $.fs.read(`${dir}/hd.json`))) as typeof meta
  } catch {
    return null
  }
  const side = meta.size ?? 0
  const base = await bytes('face-hd.rgb')
  if (base === null || side === 0 || base.length !== side * side * 3) return null
  const pixels = await bytes('scene-hd.rgb')
  const width = meta.sceneWidth ?? 0
  const height = meta.sceneHeight ?? 0
  const scene = pixels !== null && pixels.length === width * height * 3 ? { pixels, width, height } : null
  const talk = await bytes('face-talk-hd.rgb')
  const deny = await bytes('face-deny-hd.rgb')
  return { side, base, talk, deny, scene, stamp: hdStamp(base, talk, deny, pixels) }
}

// Where the HD pictures go, one file per picture key: kitty reads them
// itself, so a change of picture sends a path, not a megabyte through the
// terminal, and the face no longer blinks out while one arrives. Memory, on
// Linux; shared by sessions, a key always meaning the same pixels.
const HD_DIR = '/dev/shm/avatar7-hd'
const hdPath = (key: string): string => `${HD_DIR}/${key.replace(/[^A-Za-z0-9.-]/g, '_')}.rgba`

// $.fs.write takes text: the pixels go as base64, decoded beside.
async function writeHd($: Engine, key: string, rgba: Uint8Array): Promise<void> {
  const path = hdPath(key)
  await $.fs.write(`${path}.b64`, rgba.toBase64())
  const done = await $.process.run(['sh', '-c', 'base64 -d "$1.b64" > "$1.part" && mv "$1.part" "$1" && rm -f "$1.b64"', 'sh', path])
  if (done.exitCode !== 0) throw new Error(`${path}: ${done.stderr}`)
}

// The pictures already in HD_DIR, written by an earlier load or another
// session: ready, by path, so a reload makes none of them again.
async function hdOnDisk($: Engine, files: Map<string, 'pending' | 'ready'>): Promise<void> {
  const ls = await $.process.run(['sh', '-c', 'ls "$1" 2>/dev/null; true', 'sh', HD_DIR])
  for (const name of ls.stdout.split('\n')) if (name.endsWith('.rgba')) files.set(`${HD_DIR}/${name}`, 'ready')
}

// Starts writing a picture's file unless it is there or on its way; `files`,
// by path, marks it pending, then ready. `rgba`, when the render just made the
// picture, spares making it twice.
function hdEnsure($: Engine, files: Map<string, 'pending' | 'ready'>, hv: HdView, rgba?: Uint8Array): void {
  const key = hdKey(hv)
  const path = hdPath(key)
  if (files.has(path)) return
  files.set(path, 'pending')
  void writeHd($, key, rgba ?? hdFrame(hv)).then(
    () => files.set(path, 'ready'),
    err => {
      files.delete(path)
      $.ui.log(`avatar7: HD picture not written: ${String(err)}`)
    },
  )
}

async function loadFaces($: Engine, dir: string): Promise<Faces> {
  const read = async (name: string): Promise<Uint8Array | null> => {
    try {
      return Uint8Array.fromBase64((await $.fs.read(`${dir}/${name}`, { as: 'bytes' })).base64)
    } catch {
      return null
    }
  }
  const base = await read('face.rgb')
  if (base === null) throw new Error(`${dir}/face.rgb unreadable`)
  return { base, talk: await read('face-talk.rgb'), deny: await read('face-deny.rgb'), hd: isHdTerminal ? await loadHd($, dir) : null }
}


// A scene layer's backdrop, read from the persona's folder beside its faces.
async function loadScenes($: Engine, dir: string, persona: Persona): Promise<Persona> {
  for (const layer of persona.ambient ?? []) {
    if (layer.kind !== 'scene' || layer.file === undefined) continue
    try {
      layer.pixels = Uint8Array.fromBase64((await $.fs.read(`${dir}/${layer.file}`, { as: 'bytes' })).base64)
    } catch {
      $.ui.log(`avatar7: ${dir}/${layer.file} unreadable, run tools/bake_scene.py`)
    }
  }
  return persona
}

// A private complement, kept out of the repository: ~/.config/avatar7/personas/<id>.json
// adds scenes (events), extends the character (persona, asks), may rename the
// user (nobody). Read with cat, as the engine's reads stay in the plugin folder.
export type Private = { persona?: string; events?: Story[]; asks?: string; nobody?: string }
export const withPrivate = (pub: Persona, priv: Private | null): Persona => {
  if (priv === null) return pub
  return {
    ...pub,
    persona: priv.persona ? `${pub.persona} ${priv.persona}` : pub.persona,
    events: [...(pub.events ?? []), ...(priv.events ?? []).filter(e => typeof e.story === 'string')],
    asks: priv.asks ? (pub.asks ? `${pub.asks}; ${priv.asks}` : priv.asks) : pub.asks,
    nobody: priv.nobody ?? pub.nobody,
  }
}
const privateArgv = (id: string): string[] => ['sh', '-c', 'cat "$HOME/.config/avatar7/personas/$1.json" 2>/dev/null; true', 'avatar7-private', id]

// The persona as written in the repository, completed by the private file if any.
async function readPersona($: Engine, id: string): Promise<Persona> {
  const dir = `${$.plugin.root}/personas/${id}`
  const pub = JSON.parse(String(await $.fs.read(`${dir}/persona.json`))) as Persona
  let priv: Private | null = null
  const out = (await $.process.run(privateArgv(id))).stdout.trim()
  if (out !== '') {
    try {
      priv = JSON.parse(out) as Private
    } catch {
      $.ui.log(`avatar7: ~/.config/avatar7/personas/${id}.json is not valid JSON, ignored`)
    }
  }
  return loadScenes($, dir, withPrivate(pub, priv))
}

type Guest = { id: string; persona: Persona; faces: Faces }

// What speaking changes, in one object so speak() (a file-level function, as
// the engine requires for $) can: the line under the face, the queue, a
// visiting persona and whether its face shows, the question put to the user,
// each persona's chat with the user, and the avatar's last lines.
type Stage = {
  typing: Typing
  queue: Queued[]
  guest: Guest | null
  isGuestShown: boolean
  openQuestion: { text: string; at: number } | null
  chats: Map<string, string[]>
  recent: string[]
}

async function loadGuest($: Engine, id: string): Promise<Guest | null> {
  try {
    const dir = `${$.plugin.root}/personas/${id}`
    const persona = await readPersona($, id)
    return { id, persona, faces: await loadFaces($, dir) }
  } catch {
    return null
  }
}



// One JSON-RPC call to the personas' mem7; '' when it does not answer.
async function mem7($: Engine, at: MemoryAt, body: string): Promise<string> {
  try {
    return (await $.process.run(rpcArgv(at), { stdin: body, timeoutMs: 6_000 })).stdout
  } catch {
    return ''
  }
}

// What the persona remembers for a line: its last journals, and the
// exchanges that match what was said.
async function remembered($: Engine, at: MemoryAt, agent: string, query: string): Promise<string> {
  const latest = parseRecall(await mem7($, at, recallBody(agent, ['journal'], RECALL_JOURNALS)))
  if (query.trim() === '') return memoryNote(latest, [])
  const matched = parseContext(await mem7($, at, contextBody(agent, query, ['journal'], RECALL_JOURNALS + RECALL_OLD_JOURNALS)))
  const episodes = parseContext(await mem7($, at, contextBody(agent, query, ['episode'], RECALL_EPISODES)))
  return memoryNote(journalsFor(latest, matched), episodes)
}

async function keep($: Engine, at: MemoryAt, agent: string, value: string, tags: string[]): Promise<void> {
  await mem7($, at, storeBody(agent, episodeKey(agent, new Date()), value, ['episode', ...tags], EPISODE_TTL_S))
}

// The persona sums up, in its own voice, the exchanges since its last journal.
async function summarize($: Engine, at: MemoryAt, agent: string, voice: Persona, userName: string): Promise<void> {
  const journals = parseRecall(await mem7($, at, recallBody(agent, ['journal'], 1)))
  const episodes = unsummed(parseRecall(await mem7($, at, recallBody(agent, ['episode'], CONSOLIDATE_MAX))), journals)
  if (episodes.length === 0) return
  const r = await $.model.complete({
    model: 'haiku',
    system: personalize(voice.persona, userName, voice.nobody) + STYLE,
    prompt: journalPrompt(episodes, userName !== '' ? userName : 'the user'),
    maxTokens: 200,
    timeoutMs: 30_000,
  })
  const journal = journalFrom(r)
  // Nothing worth keeping is a journal too: the same exchanges are not read again.
  await mem7($, at, storeBody(agent, journalKey(agent, new Date()), journal ?? 'Nothing worth keeping.', ['journal']))
}

// What a line needs from the session around it, read when the line is picked.
type Speaking = {
  voice: Persona
  voiceId: string
  isGuestTurn: boolean
  // The other in a dialogue, by id: the visit goes to both memories.
  otherId: string
  memory: MemoryAt | null
  // The persona on duty, by name: whom a guest's turn speaks to.
  host: string
  asked: string
  userName: string
  relay: Relay
  // The frame now: it moves on while the line is written and voiced.
  now: () => number
  say: (ask: Ask) => void
}

// One line, from the model (or as written) to the voice: written, typed under
// the face, synthesized and played; the speaking slot is given back at the end.
async function speak($: Engine, stage: Stage, ask: Ask, c: Speaking): Promise<void> {
  try {
    // The line: a greeting as written, anything else from the model.
    // A consultation and a chat keep all their sentences.
    const isConsult = isOpinion(ask)
    const isChat = typeof ask === 'object' && 'chat' in ask
    const write = async (): Promise<string> => {
      const need = reads(ask)
      const conversation =
        need === null
          ? ''
          : (await $.session.messages())
              .filter(m => m.text.trim() !== '')
              .slice(-need.count)
              .map(m => `${m.role}: ${m.text.replace(/\s+/g, ' ').trim().slice(0, need.chars)}`)
              .join('\n')
      const other = c.isGuestTurn ? c.host : (stage.guest?.persona.name ?? 'a visitor')
      const prompt = promptFor(ask, { voice: c.voice, other, conversation, chatPast: stage.chats.get(c.voiceId) ?? [], asked: c.asked, recent: stage.recent })
      if (prompt === null) return typeof ask === 'object' && 'greet' in ask ? ask.greet : ''
      const past = c.memory !== null && recalls(ask) ? await remembered($, c.memory, c.voiceId, queryFor(ask, c.asked, other)) : ''
      const r = await $.model.complete({
        model: 'haiku',
        system: personalize(c.voice.persona, c.userName, c.voice.nobody) + STYLE,
        prompt: prompt + past,
        maxTokens: isOpinion(ask) ? 160 : 80,
        timeoutMs: 15_000,
      })
      return lineFrom(r, ask, c.voice, c.now(), c.userName)
    }
    const text = typeof ask === 'object' && 'greet' in ask ? ask.greet : await write()
    if (text === '') return
    // An opinion that ends on a question opens the answer field too.
    // A chat's question is answered by the next chat.
    if (typeof ask === 'object' && 'chat' in ask) {
      const past = [...(stage.chats.get(c.voiceId) ?? []), `User: ${ask.chat}`, `${c.voice.name}: ${text}`]
      stage.chats.set(c.voiceId, past.slice(-CHAT_LINES))
    }
    if (ask === 'question' || (isConsult && !isChat && text.endsWith('?'))) {
      stage.openQuestion = { text, at: c.now() }
      $.ui.invalidate('ui.render')
    }
    stage.recent.push(text)
    if (stage.recent.length > RECENT_LINES) stage.recent.shift()
    if (c.memory !== null) {
      const at = c.memory
      const episode = episodeOf(ask, c.voice.name, text)
      if (episode !== null) void keep($, at, c.voiceId, episode.value, [episode.kind])
      if (typeof ask === 'object' && 'duo' in ask && ask.turn === DUO_TURNS - 1 && c.otherId !== '') {
        const last = `${c.voice.name}: ${text}`
        const otherName = c.isGuestTurn ? c.host : (stage.guest?.persona.name ?? c.otherId)
        void keep($, at, c.voiceId, visitOf(ask.history, last, otherName), ['visit'])
        void keep($, at, c.otherId, visitOf(ask.history, last, c.voice.name), ['visit'])
      }
    }
    const isDuo = typeof ask === 'object' && 'duo' in ask
    const shown = isDuo ? `${c.voice.name}: ${text}` : text
    const isQuiet = await read($, isMuted)
    stage.typing = start(stage.typing, shown, isQuiet, c.now())
    const seq = stage.typing.seq
    await update($, line, () => ({ text: shown, at: c.now() }) satisfies Line)
    if (!isQuiet) {
      const made = await $.process.run(synthArgv(c.voiceId, c.voice, await read($, volume)), {
        stdin: text,
        timeoutMs: 30_000,
      })
      const heard = voiced(stage.typing, seq, made.stdout, c.now(), FRAME_MS)
      stage.typing = heard.t
      const { wav, ms } = heard
      if (wav !== '') {
        // Detached, so a reload of this module no longer cuts the line;
        // the voice is held for the WAV's length plus PowerShell's start.
        await update($, isVoicing, () => true)
        await $.process.run(detachedArgv(playArgv(wav, c.relay.session, SAPI_PLAY)))
        await $.clock.sleep(ms + PLAY_START_MS)
      }
    }
    if (typeof ask === 'object' && 'duo' in ask && ask.turn < DUO_TURNS - 1) {
      c.say({ ...ask, turn: ask.turn + 1, history: [...ask.history, `${c.voice.name}: ${text}`] })
    }
  } catch (err) {
    // A synthesis past its timeout, a model call that failed: the line
    // is lost, the reason kept.
    $.ui.log(`avatar7: a line was lost: ${String(err)}`, { to: 'debug' })
  } finally {
    // A dialogue ends on its last turn, or on a turn that said nothing.
    if (typeof ask === 'object' && 'duo' in ask && !stage.queue.some(q => typeof q.ask === 'object' && 'duo' in q.ask)) {
      stage.isGuestShown = false
      stage.guest = null
    }
    stage.typing = end(stage.typing)
    if (await read($, isVoicing)) await update($, isVoicing, () => false)
  }
}

export const register: Register = (on, options) => {
  const userName = typeof options.user_name === 'string' ? options.user_name.trim() : ''
  // The personas' own mem7, or null: then they forget between sessions.
  const memory = memoryAt(options)
  let frame = 0
  // The face: its mood and the waits that hold it (mood.ts).
  let face: Face = calm
  // What speaking changes: the line, the queue, the guest, the open question,
  // the chats and the last lines (Stage); speak() takes it whole.
  const stage: Stage = { typing: silent, queue: [], guest: null, isGuestShown: false, openQuestion: null, chats: new Map(), recent: [] }
  // The remote voice, its own state (relay.ts); relay.session is '' in a
  // background session.
  const relay = newRelay()
  let sessionDir = ''
  let lastPrompt = ''
  let streak: Streak = { mood: 'watch', count: 0 }
  // The persona's own events: on unless /avatar events off; the next one's frame.
  let eventsOn = true
  // Visits from other personas, a share of the events, switched apart.
  let visitsOn = true
  let nextEventAt = Infinity
  const nextGap = (): number => EVENT_MIN_FRAMES + Math.random() * EVENT_SPAN_FRAMES
  // A visit: the guest read (loadGuest), then the host opens.
  const startDuo = (g: Guest, topic: Duo['topic']): boolean => {
    // One visit at a time: a second would take over the first's turns.
    if (stage.guest !== null) return false
    stage.guest = g
    face = react(face, 'watch', frame, 30)
    speakLater({ duo: g.id, turn: 0, topic, history: [] })
    return true
  }
  const startEvent = (ask: Ask): void => {
    if (typeof ask === 'object' && 'story' in ask) {
      face = stageFace(face, ask.mood, frame, 60)
    }
    speakLater(ask)
  }
  let faces: Faces | null = null
  let who: Persona | null = null
  // The avatar `who` was read from, so a line keeps its voice through a switch.
  let whoId = ''
  let size = W
  // The ambient's geometry, set at each render: the margins either side of
  // the face, the band under the text, in cells; and its own clock, which
  // runs faster on a refusal or an error and slower while a human decides.
  let ambLeft = 0
  let ambRight = 0
  let ambBand = 0
  let ambField: Field = { width: 0, height: 0, sceneTop: 0, sceneBottom: 0 }
  let ambT = 0
  let asked = ''
  const speakLater = (ask: Ask): void => {
    stage.queue = enqueue(stage.queue, ask, frame)
  }
  // The last `say` of each mod, for /avatar voices.
  const saidHere = new Map<string, Say>()
  // An avatar picked in the pane or by /avatar; the clock swaps it in.
  let pendingAvatar: string | null = null
  let avatarPick = 0
  let isPicking = false
  // The field where the user asks the avatar's opinion, open or not.
  let isConsulting = false
  // The field where the user talks to the avatar personally.
  let isChatting = false
  // Display names for the picker, read from each persona.json.
  const names: Record<string, string> = {}
  let lastModel = ''

  // The face's frame, as draw.ts takes it: whoever is shown (the guest
  // during a visit), its mood and weather, read once per frame.
  const view = (): View => {
    const isGuest = stage.isGuestShown && stage.guest !== null
    return {
      frame,
      frameMs: FRAME_MS,
      mood: face.mood,
      faces: isGuest && stage.guest !== null ? stage.guest.faces : faces,
      persona: isGuest && stage.guest !== null ? stage.guest.persona : who,
      isHeard: isHeard(stage.typing, frame),
      glitch: face.isStaged ? SCENE_GLITCH : 1,
      size,
      layers: ambientLayers(),
      field: ambField,
      ambLeft,
      ambT,
    }
  }
  const cells = (): string => faceCells(view())
  // The face last blitted, to skip the frames that change nothing.
  let lastFace = ''

  // The face as a real image (hd.ts), where the terminal draws pictures and
  // the persona has its HD bake: the band's width in columns, set at each
  // render; whether the last render mounted the Image; the key of the
  // picture it shows, so the clock blits only when the picture changes; and
  // the last pictures made, since the same few come back (moods, mouth).
  let hdColumns = 0
  // The art pixel's side (hd.ts GRAINS): /avatar pixel <n>, kept in $.store.
  let grain: number = DEFAULT_GRAIN
  type HdSource = { file: string; format: 'rgba'; width: number; height: number } | { rgba: string; width: number; height: number }
  type HdBand = HdView['band']
  // The picture files written, or being written, by path.
  const hdFiles = new Map<string, 'pending' | 'ready'>()
  // Each band's source as shown, kept as one object, so a redraw that
  // changes nothing hands the engine the very same source and nothing is
  // sent; and its key.
  const hdShown: Record<HdBand, { source: HdSource; key: string } | null> = { face: null, under: null }
  const isHdShown = (): boolean => hdShown.face !== null
  // The pane's size and the frame it last changed (hd.ts isSettled).
  const hdResize: Settle = { size: '', since: 0 }
  let isHdSettled = false
  // The scene layers with their HD bake in place of the 512 px one, made
  // once per layer list so the fitted scene's cache holds.
  const hdLayersOf = new WeakMap<AmbientLayer[], AmbientLayer[]>()
  const hdLayers = (layers: AmbientLayer[], hd: Hd | null | undefined): AmbientLayer[] => {
    const scene = hd?.scene
    if (scene === null || scene === undefined) return layers
    let swapped = hdLayersOf.get(layers)
    if (swapped === undefined) {
      swapped = layers.map(l => (l.kind === 'scene' ? { ...l, pixels: scene.pixels, width: scene.width, height: scene.height } : l))
      hdLayersOf.set(layers, swapped)
    }
    return swapped
  }
  const hdView = (band: HdBand): HdView | null => {
    const v = view()
    const hd = v.faces?.hd
    if (!isHdTerminal || hd === undefined || hd === null || v.persona === null || hdColumns === 0) return null
    if (band === 'under' && ambBand === 0) return null
    const isGuest = stage.isGuestShown && stage.guest !== null
    // The weather loops over HD_LOOP pictures, each made once.
    const step = Math.floor(ambT / HD_STEP_S) % HD_LOOP
    const isFace = band === 'face'
    return {
      who: isGuest && stage.guest !== null ? stage.guest.id : whoId,
      band,
      hd: isFace ? hd : null,
      mood: isFace ? v.mood : v.mood === 'deny' ? 'deny' : 'idle',
      face: pickHdFace(hd, v.mood, v.isHeard, noise(v.frame >> 2, 7)),
      glitchStep: isFace && v.mood === 'deny' ? 1 + ((v.frame >> 2) % GLITCH_STEPS) : 0,
      glitch: v.glitch,
      grain,
      color: v.persona.color ?? '#00ff9c',
      cutout: v.persona.cutout ?? 12,
      columns: hdColumns,
      rows: isFace ? size / 2 : ambBand,
      size: isFace ? size : 0,
      layers: hdLayers(v.layers, hd),
      field: v.field,
      top: isFace ? 0 : size + TEXT_ROWS * 2,
      t: step * HD_STEP_S,
      step,
      isStorm: v.mood === 'deny',
      stamp: hd.stamp,
    }
  }
  const fileSource = (hv: HdView): HdSource => ({ file: hdPath(hdKey(hv)), format: 'rgba', ...hdSize(hv.columns, hv.rows) })
  // The source a band shows at a render: its picture if written, else the
  // last one until the clock swaps the new one in, else (the first) bytes;
  // and the view whose file is still to write.
  // The engine takes at most 2 MiB of Image source a tree: a band whose
  // bytes would pass what is left waits for its file, and the clock renders
  // again once it is written.
  const HD_INLINE_MAX = 2_000_000
  const hdRender = (band: HdBand, budget: { left: number }): { source: HdSource | null; toWrite: HdView | null; rgba?: Uint8Array } => {
    const hv = hdView(band)
    if (hv === null) {
      hdShown[band] = null
      return { source: null, toWrite: null }
    }
    const key = hdKey(hv)
    const was = hdShown[band]
    const isReady = hdFiles.get(hdPath(key)) === 'ready'
    let rgba: Uint8Array | undefined
    if (isReady) {
      if (was?.key !== key) hdShown[band] = { source: fileSource(hv), key }
    } else {
      const { width, height } = hdSize(hv.columns, hv.rows)
      if (was === null || was.source.width !== width || was.source.height !== height) {
        // Mid-resize: the last picture, stretched, and nothing made.
        if (was !== null && !isHdSettled) return { source: was.source, toWrite: null }
        const inline = Math.ceil((width * height * 4) / 3) * 4
        if (inline > budget.left) return { source: was?.source ?? null, toWrite: hv }
        budget.left -= inline
        rgba = hdFrame(hv)
        hdShown[band] = { source: { rgba: rgba.toBase64(), width, height }, key }
      }
    }
    return { source: hdShown[band]?.source ?? null, toWrite: isReady ? null : hv, rgba }
  }
  // At a frame: the band's new picture to swap in once written, or the view
  // whose file is still to write.
  const hdTick = (band: HdBand): { swap: HdSource | null; toWrite: HdView | null; isRefit: boolean } => {
    const hv = hdView(band)
    const shown = hdShown[band]
    if (hv === null) return { swap: null, toWrite: null, isRefit: false }
    const key = hdKey(hv)
    // Not shown yet: its file, once written, mounts it at a render.
    if (shown === null) return { swap: null, toWrite: null, isRefit: hdFiles.get(hdPath(key)) === 'ready' }
    if (key === shown.key) return { swap: null, toWrite: null, isRefit: false }
    // A new size: once it holds, a render makes its picture.
    const { width, height } = hdSize(hv.columns, hv.rows)
    if (shown.source.width !== width || shown.source.height !== height) return { swap: null, toWrite: null, isRefit: isSettled(hdResize, hdResize.size, frame) }
    if (hdFiles.get(hdPath(key)) !== 'ready') return { swap: null, toWrite: hv, isRefit: false }
    const source = fileSource(hv)
    hdShown[band] = { source, key }
    return { swap: source, toWrite: null, isRefit: false }
  }

  // The weather of whoever is shown: the guest's during a visit.
  const ambientLayers = (): AmbientLayer[] =>
    (stage.isGuestShown && stage.guest !== null ? stage.guest.persona.ambient : who?.ambient) ?? []

  // The repaints of the ambient's Rasters, the ones the last render mounted.
  const ambientBlits = (): { requestId: string; key: string; columns: number; rows: number; cells: string }[] => {
    const layers = ambientLayers()
    if (layers.length === 0) return []
    const isStorm = face.mood === 'deny'
    const rows = size / 2
    const paint = (key: string, x0: number, y0: number, columns: number, height: number) => ({
      requestId: PANE,
      key,
      columns,
      rows: height,
      cells: ambientCells(layers, ambField, x0, y0, columns, height, ambT, isStorm),
    })
    return [
      // Beside the face only in half blocks: the HD picture holds its own scene.
      ...(ambLeft > 0 && !isHdShown() ? [paint(AMB_LEFT, 0, 0, ambLeft, rows)] : []),
      ...(ambRight > 0 && !isHdShown() ? [paint(AMB_RIGHT, ambLeft + size, 0, ambRight, rows)] : []),
      ...(ambBand > 0 && hdShown.under === null ? [paint(AMB_BAND, 0, size + TEXT_ROWS * 2, ambField.width / QUAD, ambBand)] : []),
    ]
  }

  const describe = (e: Record<string, unknown>): string => {
    const hint = e.command ?? e.file_path ?? e.pattern ?? e.url ?? ''
    return `${String(e.tool)} ${String(hint).slice(0, 80)}`.trim()
  }

  on('session.start', async ($, e, next) => {
    // A daemon's background session (a spare kept warm, a `claude --bg`)
    // inherits the plugin dirs but nobody watches it: no face, no voice.
    const kind = await $.process.run(['sh', '-c', 'printf %s "$CLAUDE_CODE_SESSION_KIND"'])
    if (kind.stdout === 'bg') return next(e)
    const env = await $.process.run(['sh', '-c', 'printf %s "$TERM|$TERM_PROGRAM|$AVATAR7_HD"'])
    isHdTerminal = drawsPictures(env.stdout)
    // Pictures a day old belong to panes long gone.
    if (isHdTerminal) await $.process.run(['sh', '-c', `mkdir -p ${HD_DIR} && find ${HD_DIR} -type f -mmin +1440 -delete`])
    // A reload mid-line kills the timer that would lower it: jukebox7 would
    // stay ducked.
    if (await read($, isVoicing)) await update($, isVoicing, () => false)
    await relayOpen($, relay)
    sessionDir = e.cwd.split('/').filter(Boolean).at(-1) ?? '/'

    await $.command.register({
      name: 'avatar',
      description: `Open the avatar pane, or switch: /avatar ${AVATARS.join('|')}; /avatar event, /avatar duo [id], /avatar events on|off, /avatar visits on|off, /avatar remote on|off, /avatar pixel ${GRAINS.join('|')}`,
    })
    await $.command.register({ name: 'avatar-mute', description: 'Toggle the avatar voice' })
    await $.command.register({ name: 'avatar-talk', description: 'Ask the avatar what it thinks of the conversation' })
    await $.command.register({
      name: 'avatar-chat',
      description: 'Talk to the avatar personally, not about the session: /avatar-chat <what you say>',
    })
    await $.command.register({
      name: 'avatar-ask',
      description: 'Ask the avatar its opinion on the session: /avatar-ask <question>',
    })

    const storedVolume = await $.store.get('volume')
    if (typeof storedVolume === 'number') await update($, volume, () => storedVolume)

    const stored = await $.store.get('avatar')
    const id = typeof stored === 'string' && AVATARS.includes(stored) ? stored : DEFAULT
    await update($, onDuty, () => id)
    try {
      const dir = `${$.plugin.root}/personas/${id}`
      who = await readPersona($, id)
      whoId = id
      await update($, tint, () => who?.color ?? '')
      await update($, station, () => ({ name: who?.name ?? '', artists: who?.station ?? [] }))
      faces = await loadFaces($, dir)
    } catch {
      $.ui.log(`avatar7: personas/${id} unreadable, run tools/bake.py ${id}`)
    }
    if (isHdTerminal) await hdOnDisk($, hdFiles)
    if (memory !== null && who !== null) {
      const voice = who
      void summarize($, memory, id, voice, userName).catch(err => $.ui.log(`avatar7: no journal for ${id}: ${String(err)}`, { to: 'debug' }))
    }
    for (const each of AVATARS) {
      try {
        names[each] = (JSON.parse(String(await $.fs.read(`${$.plugin.root}/personas/${each}/persona.json`))) as Persona).name
      } catch {
        names[each] = each
      }
    }

    const last = await read($, line)
    stage.typing = restored(stage.typing, last.text)
    eventsOn = (await $.store.get('events')) !== false
    const storedGrain = await $.store.get('pixel')
    if (typeof storedGrain === 'number' && (GRAINS as readonly number[]).includes(storedGrain)) grain = storedGrain
    visitsOn = (await $.store.get('visits')) !== false
    nextEventAt = frame + nextGap()

    $.clock.every(FRAME_MS, () => {
      frame += 1
      if (pendingAvatar !== null) {
        const id = pendingAvatar
        pendingAvatar = null
        const pick = ++avatarPick
        void (async () => {
          const dir = `${$.plugin.root}/personas/${id}`
          // Loaded whole before anything switches: a persona that cannot be
          // read leaves the one on duty, and of two quick picks the last wins.
          const chosen = await readPersona($, id)
          const chosenFaces = await loadFaces($, dir)
          if (pick !== avatarPick) return
          who = chosen
          whoId = id
          faces = chosenFaces
          await update($, tint, () => who?.color ?? '')
          await update($, station, () => ({ name: who?.name ?? '', artists: who?.station ?? [] }))
          await $.store.set('avatar', id)
          await update($, onDuty, () => id)
          await $.ui.open({ id: PANE, title: who.name })

          // Through the queue like any line: never over another voice, and
          // jukebox7 hears isVoicing for it too.
          speakLater({ greet: personalize(who.greeting, userName, who.nobody) })
          if (memory !== null) await summarize($, memory, id, chosen, userName)
        })().catch(err => $.ui.log(`avatar7: personas/${id} could not take over: ${String(err)}`))
      }
      face = tick(face, frame, WAIT_CAP_FRAMES)
      relayTick($, relay, frame, {
        face: () => {
          if (who === null) return undefined
          const shownWho = stage.isGuestShown && stage.guest !== null ? stage.guest.persona : who
          const base = {
            persona: stage.isGuestShown && stage.guest !== null ? stage.guest.id : whoId,
            name: shownWho.name,
            color: shownWho.color ?? '',
            mood: face.mood,
            line: stage.typing.text,
            seq: stage.typing.seq,
            speakMs: Math.max(0, stage.typing.speakUntil - stage.typing.from) * FRAME_MS,
            isSpeaking: isHeard(stage.typing, frame),
            question: stage.openQuestion?.text ?? '',
            avatars: AVATARS.map(id => ({ id, name: names[id] ?? id })),
            eventsOn,
            visitsOn,
            session: [relay.session.slice(0, 8), sessionDir, lastPrompt === '' ? '' : `"${lastPrompt.slice(0, 40)}"`].filter(Boolean).join(' / '),
          }
          return (async (): Promise<Mirror> => ({ ...base, isMuted: await read($, isMuted), volume: await read($, volume) }))()
        },
        press: async r => {
          if (r.cmd === 'talk') speakLater('talk')
          else if (r.cmd === 'ask') {
            const question = r.text.replace(/\s+/g, ' ').trim().slice(0, CONSULT_CHARS_ASKED)
            if (question !== '') speakLater({ consult: question })
          } else if (r.cmd === 'chat') {
            const said = r.text.replace(/\s+/g, ' ').trim().slice(0, CONSULT_CHARS_ASKED)
            if (said !== '') speakLater({ chat: said })
          } else if (r.cmd === 'answer') {
            const answer = r.text.replace(/\s+/g, ' ').trim().slice(0, ASKED_CHARS)
            const q = stage.openQuestion
            if (answer !== '' && q !== null) {
              stage.openQuestion = null
              speakLater({ question: q.text, answer })
            }
          } else if (r.cmd === 'avatar') {
            if (AVATARS.includes(r.id) && r.id !== whoId) pendingAvatar = r.id
          } else if (r.cmd === 'mute') await update($, isMuted, was => !was)
          else if (r.cmd === 'events') {
            eventsOn = !eventsOn
            await $.store.set('events', eventsOn)
          } else if (r.cmd === 'visits') {
            visitsOn = !visitsOn
            await $.store.set('visits', visitsOn)
          } else if (r.cmd === 'volume') {
            const step = r.step * VOLUME_STEP
            const v = await update($, volume, was => Math.min(100, Math.max(0, was + step)))
            await $.store.set('volume', v)
          }
          $.ui.invalidate('ui.render')
        },
      })
      let isRefit = false
      for (const [band, key] of [['face', FACE], ['under', AMB_BAND]] as const) {
        const tick = hdTick(band)
        if (tick.toWrite !== null) hdEnsure($, hdFiles, tick.toWrite)
        if (tick.swap !== null) void $.ui.blit({ requestId: PANE, key, source: tick.swap })
        isRefit ||= tick.isRefit
      }
      if (isRefit) $.ui.invalidate('ui.render')
      // Sent only when it changed: each blit redraws the screen, and in a
      // terminal without synchronized output (WezTerm) the cursor jumped at
      // 15 i/s. A full render draws the face afresh, so a skip never leaves
      // a stale one.
      if (!isHdShown()) {
        const drawn = cells()
        if (drawn !== lastFace) {
          lastFace = drawn
          void $.ui.blit({ requestId: PANE, key: FACE, columns: size, rows: size / 2, cells: drawn })
        }
      }
      if (frame % AMBIENT_FRAMES === 0) {
        ambT += ((AMBIENT_FRAMES * FRAME_MS) / 1000) * (face.mood === 'deny' || face.mood === 'error' ? 2 : face.mood === 'wait' ? 0.5 : 1)
        for (const each of ambientBlits()) void $.ui.blit(each)
      }
      const typedOn = typeOn(stage.typing, frame)
      if (typedOn !== stage.typing) {
        stage.typing = typedOn
        $.ui.invalidate('ui.render')
      } else if (frame % REFIT_FRAMES === 0) {
        $.ui.invalidate('ui.render')
      }

      if (face.askSince !== null && frame - face.askSince === ASK_FRAMES) {
        speakLater({ mood: 'wait', event: `call waiting for the user's permission: ${face.askCall}` })
      }

      // Now and then, when nothing else happens, a moment of the persona's own.
      if (
        eventsOn &&
        who !== null &&
        frame >= nextEventAt &&
        stage.queue.length === 0 &&
        !stage.typing.isSpeaking &&
        !isWaiting(face) &&
        stage.openQuestion === null &&
        frame - stage.typing.lastSpoke > EVENT_QUIET_FRAMES
      ) {
        nextEventAt = frame + nextGap()
        // One event in three is a visit from another persona.
        const gid = visitsOn && Math.random() < 1 / 3 ? pickGuest(AVATARS, whoId, Math.random(), who.friends) : undefined
        if (gid !== undefined) {
          void loadGuest($, gid).then(g => {
            if (g !== null) startDuo(g, Math.random() < 0.5 ? 'session' : 'stories')
          })
        } else {
          const ev = pickEvent(who.events ?? [], who.asks !== undefined, Math.random(), Math.random())
          if (ev !== undefined) startEvent(ev)
        }
      }
      if (stage.openQuestion !== null && frame - stage.openQuestion.at > QUESTION_FRAMES) {
        stage.openQuestion = null
        $.ui.invalidate('ui.render')
      }

      stage.queue = fresh(stage.queue, frame)
      // A line may wait a moment for a mod to say better (a mesh7 verdict).
      const ready = stage.queue.findIndex(q => typeof q.ask !== 'object' || !('after' in q.ask) || (q.ask.after ?? 0) <= frame)
      const first = stage.queue[ready]
      if (first === undefined || stage.typing.isSpeaking || who === null) return
      stage.queue = stage.queue.filter((_, i) => i !== ready)
      const ask = first.ask
      stage.typing = begin(stage.typing, frame)
      // In a dialogue the guest speaks the odd turns, with its own voice and face.
      const isGuestTurn = typeof ask === 'object' && 'duo' in ask && ask.turn % 2 === 1 && stage.guest !== null
      const voice = isGuestTurn && stage.guest !== null ? stage.guest.persona : who
      const voiceId = isGuestTurn && stage.guest !== null ? stage.guest.id : whoId
      const otherId = isGuestTurn ? whoId : (stage.guest?.id ?? '')
      stage.isGuestShown = isGuestTurn
      const host = who.name
      $.clock.after(1, () =>
        speak($, stage, ask, { voice, voiceId, isGuestTurn, otherId, memory, host, asked, userName, relay, now: () => frame, say: speakLater }),
      )
    })

    // Opened after the plugins beneath have started: the pane opened last is
    // the one shown, and mesh7-pane or jukebox7 would take that place. Once
    // more a moment later, should one of them open late.
    const started = await next(e)
    void $.ui.open({ id: PANE, title: who?.name ?? 'avatar7' })
    $.clock.after(1500, () => void $.ui.open({ id: PANE, title: who?.name ?? 'avatar7' }))
    return started
  })

  on('command.run', { command: 'avatar' }, async ($, e) => {
    const id = e.args.trim().toLowerCase()

    if (id === '') {
      const opened = await $.ui.open({ id: PANE, title: who?.name ?? 'avatar7' })
      return { text: opened.isPlaced ? `${who?.name ?? 'avatar7'} is watching.` : 'The pane needs a wider terminal.' }
    }
    // The mods heard asking for a voice, and what they asked.
    // The persona's own events: one now, or switched on or off for good.
    if (id === 'event') {
      const ev = who === null ? undefined : pickEvent(who.events ?? [], who.asks !== undefined, Math.random(), Math.random())
      if (ev === undefined) return { text: `${who?.name ?? 'avatar7'} has no events of its own yet.` }
      startEvent(ev)
      return { text: ev === 'question' ? `${who?.name} has a question.` : `Something happens to ${who?.name}.` }
    }
    // A visit now: /avatar duo <id>, or a guest picked at random.
    if (id === 'duo' || id.startsWith('duo ')) {
      const want = id.slice(3).trim()
      const gid = want !== '' ? want : pickGuest(AVATARS, whoId, Math.random(), who?.friends)
      if (gid === undefined || !AVATARS.includes(gid) || gid === whoId) {
        return { text: `Pick another avatar: ${AVATARS.filter(a => a !== whoId).join(', ')}.` }
      }
      const g = await loadGuest($, gid)
      if (g === null) return { text: `personas/${gid} is unreadable.` }
      if (!startDuo(g, Math.random() < 0.5 ? 'session' : 'stories')) return { text: `${stage.guest?.persona.name ?? 'A guest'} is visiting already.` }
      return { text: `${g.persona.name} visits ${who?.name ?? 'avatar7'}.` }
    }
    if (id === 'visits on' || id === 'visits off') {
      visitsOn = id === 'visits on'
      await $.store.set('visits', visitsOn)
      $.ui.invalidate('ui.render')
      return { text: visitsOn ? 'The avatars visit each other again.' : 'No more visits.' }
    }
    if (id === 'events on' || id === 'events off') {
      eventsOn = id === 'events on'
      await $.store.set('events', eventsOn)
      $.ui.invalidate('ui.render')
      return { text: eventsOn ? 'The avatars live their own stories again.' : 'No more events of their own.' }
    }
    if (id === 'voices') {
      const all = [
        ...Object.entries(await read($, announcers)).map(([plugin, a]) => `${plugin} (toasts): ${a.mood}, ${a.event}`),
        ...[...saidHere].map(([plugin, a]) => `${plugin} (say): ${a.mood}, ${a.event}`),
      ]
      return { text: all.length === 0 ? 'No mod has asked for a voice in this session.' : all.join('\n') }
    }
    if (id.startsWith('pixel')) {
      const n = Number(id.slice('pixel'.length).trim())
      if (!(GRAINS as readonly number[]).includes(n)) return { text: `The pixel's size, in kitty or Ghostty: /avatar pixel ${GRAINS.join('|')} (1 smooth, 6 the half blocks' grid); now ${grain}.` }
      grain = n
      await $.store.set('pixel', n)
      $.ui.invalidate('ui.render')
      return { text: isHdTerminal ? `Pixels of ${n}.` : `Pixels of ${n}, seen in kitty or Ghostty; this terminal keeps the half blocks.` }
    }
    if (id === 'remote on') return { text: await relayOn($, relay) }
    if (id === 'remote off') return { text: await relayOff($, relay) }
    if (!AVATARS.includes(id)) return { text: `Unknown avatar. Choose one of: ${AVATARS.join(', ')}.` }

    pendingAvatar = id
    return { text: `${names[id] ?? id} takes over.` }
  })

  on('command.run', { command: 'avatar-talk' }, async () => {
    speakLater('talk')
    return { text: `${who?.name ?? 'avatar7'} reads the conversation.` }
  })

  on('command.run', { command: 'avatar-chat' }, async ($, e) => {
    const said = e.args.replace(/\s+/g, ' ').trim().slice(0, CONSULT_CHARS_ASKED)
    if (said === '') return { text: 'Usage: /avatar-chat <what you say>' }
    speakLater({ chat: said })
    return { text: `${who?.name ?? 'avatar7'} listens.` }
  })

  on('command.run', { command: 'avatar-ask' }, async ($, e) => {
    const question = e.args.replace(/\s+/g, ' ').trim().slice(0, CONSULT_CHARS_ASKED)
    if (question === '') return { text: 'Usage: /avatar-ask <question>' }
    speakLater({ consult: question })
    return { text: `${who?.name ?? 'avatar7'} reads the session and thinks it over.` }
  })

  // Every other slash command, native or custom: the listed ones earn a line,
  // the rest run untouched.
  on('command.run', async ($, e, next) => {
    const heard = commandEvent(e.command, e.args)
    if (heard !== undefined) speakLater(heard)
    return next(e)
  })

  // An automatic compaction, the main conversation's only: the manual one
  // came through /compact.
  on('session.compact', async ($, e, next) => {
    if (e.trigger === 'auto' && e.agentId === undefined) {
      speakLater({ mood: 'error', event: 'the context window filled up and the conversation was compacted on its own' })
    }
    return next(e)
  })

  on('command.run', { command: 'avatar-mute' }, async $ => {
    const muted = await update($, isMuted, was => !was)
    return { text: muted ? 'The avatar falls silent.' : 'The avatar speaks again.' }
  })

  // A session that ends gives the relay back; a /clear keeps a forced one.
  on('session.end', async ($, e, next) => {
    await relayEnd($, relay, e.reason)
    return next(e)
  })

  // A model switch is no command the mod sees (the /model picker settles it
  // after the command has run, and Remote Control or /config switch without
  // one): the model in use is compared at each turn's end.
  on('turn.complete', async ($, e, next) => {
    asked = ''
    if (relay.session !== '') {
      const model = await $.session.model()
      if (lastModel !== '' && model !== lastModel && who !== null) {
        speakLater({ mood: 'watch', event: `the assistant now runs on ${model}, no longer on ${lastModel}` })
      }
      lastModel = model
    }
    return next(e)
  })

  // Only what the user typed, at the terminal or through Remote Control.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'composer' || e.origin.kind === 'bridge') {
      asked = e.text.replace(/\s+/g, ' ').trim().slice(0, ASKED_CHARS)
      lastPrompt = asked
    }
    await relayFollow($, relay, e.origin.kind)
    return next(e)
  })

  // A mod that wants its toasts voiced publishes `announce` under its own
  // name (atelier-bell, usage-bell, jukebox7...): the avatar keeps a record
  // of each, so plugging a mod in is enough, and no mod depends on avatar7.
  const heardHere = new Map<string, Announce>()
  on('state.set', async ($, e, next) => {
    const done = await next(e)
    const w = e as { plugin: string; key: string; value: unknown }
    const s = landed(done) ? heardSay(w) : undefined
    if (s !== undefined) {
      saidHere.set(w.plugin, s)
      // A mod that speaks by say no longer has its toasts read out: one line
      // per event (jukebox7 moved from announce to say; a session that heard
      // its announce before would say each song twice).
      if (heardHere.delete(w.plugin) || (await read($, announcers))[w.plugin] !== undefined) {
        await update($, announcers, was => Object.fromEntries(Object.entries(was).filter(([k]) => k !== w.plugin)))
      }
      // The mod's line replaces the avatar's own waiting line on that call.
      if (s.tool !== undefined) stage.queue = stage.queue.filter(q => !(typeof q.ask === 'object' && 'tool' in q.ask && q.ask.tool === s.tool))
      face = s.hold === true ? hold(face, s.tool ?? 'a call', frame) : s.release === true ? release(face, s.mood, frame) : react(face, s.mood, frame)
      if (who !== null) speakLater({ mood: s.mood, event: s.event })
    }
    const a = landed(done) ? heard(w) : undefined
    if (a !== undefined) {
      heardHere.set(w.plugin, a)
      try {
        await update($, announcers, was => ({ ...was, [w.plugin]: a }))
      } catch (err) {
        $.ui.log(`avatar7 could not keep ${w.plugin}.announce: ${String(err)}`, { to: 'debug' })
      }
    }
    return done
  })

  // Their toasts, announced in the avatar's own voice past the tool-call
  // rate limits; a warning in amber.
  on('ui.toast', async ($, e, next) => {
    const from = next.origin.plugin
    const bell = from === undefined || from === 'avatar7' ? undefined : (heardHere.get(from) ?? (await read($, announcers))[from])
    if (bell !== undefined && who !== null) {
      face = react(face, bell.mood, frame, 30)
      speakLater({ mood: bell.mood, event: `${bell.event}: ${e.text}` })
    }
    return next(e)
  })

  // The verdict before the mode settles it: an ask may put up the prompt.
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision === 'ask' && e.tool_use_id !== undefined) {
      face = askFace(face, describe({ ...(e.input as Record<string, unknown>), tool: e.tool }), frame)
    }
    return verdict
  })

  on('tool.call', async ($, e, next) => {
    let ran: Awaited<ReturnType<typeof next>>
    try {
      ran = await next(e)
    } finally {
      // An interrupt at the permission prompt still ends the wait.
      face = answered(face)
    }

    const call = describe(e as unknown as Record<string, unknown>)
    const now: Mood = ran.deny !== undefined ? 'deny' : ran.isError === true ? 'error' : 'watch'

    // A held call keeps the waiting face; the others set theirs.
    face = react(face, now, frame)

    // Counted on every call, spoken or not; a broken run of failures earns
    // the short wait a failure gets.
    const was = streak
    streak = nextStreak(was, now as Streak['mood'])
    const note = streakNote(was, streak)

    const quiet = now === 'watch' && note === '' ? 45_000 / FRAME_MS : 5_000 / FRAME_MS
    // A plain success waits for silence; a refusal or a failure takes its
    // place in the queue, ahead of the calmer lines.
    if (frame - stage.typing.lastSpoke < quiet || (now === 'watch' && (stage.typing.isSpeaking || stage.queue.length > 0))) return ran
    // A refusal, a failure, or any call through mesh7 waits ~1.8 s: mesh7-pane,
    // when loaded, may say what mesh7 decided and replace this line.
    const mayBeSaid = now !== 'watch' || e.tool.startsWith('mcp__mesh7__')
    speakLater({
      ...(mayBeSaid ? { tool: e.tool, after: frame + SAY_WAIT_FRAMES } : {}),
      mood: now,
      event:
        (now === 'deny'
          ? `call DENIED: ${call} (${(ran.deny ?? ran.text ?? '').slice(0, 120)})`
          : now === 'error'
            ? `call FAILED: ${call}`
            : `call succeeded: ${call}`) + note,
    })

    return ran
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const last = await read($, line)
    const shown = last.text.slice(0, Math.floor(stage.typing.typed))
    const color = who?.color ?? '#00ff9c'

    if (e.surface !== 'terminal') {
      const { Box, Text } = $.ui.resolve(e)
      return (
        <Box flexDirection="column">
          <Text>{who?.name ?? 'avatar7'}</Text>
          <Text>{shown}</Text>
        </Box>
      )
    }

    const { Box, Text, Raster, Button, Input, Image } = $.ui.resolve(e)
    const muted = await read($, isMuted)
    const vol = await read($, volume)
    const current = await read($, onDuty)
    size = fit(e.props.bodyColumns, e.props.scroll.bodyRows)
    // Rules in the persona's color between the face, the line and the
    // controls, drawn as a terminal's: a label, a status on the right, a
    // cursor that blinks at each redraw, dashes that glitch on a denial.
    const cols = Math.max(8, e.props.bodyColumns)
    // The weather fills the margins beside the face and the band under the
    // text. The band is drawn as tall as it could be and sits in the room the
    // text leaves, anchored to its bottom: when the line wraps or a field
    // opens, its faded top is clipped instead of the face being squeezed.
    const layers = ambientLayers()
    const isAmbient = layers.length > 0
    ambLeft = isAmbient ? Math.floor((cols - size) / 2) : 0
    ambRight = isAmbient ? cols - size - ambLeft : 0
    ambBand = isAmbient ? Math.max(0, e.props.scroll.bodyRows - size / 2 - 4) : 0
    ambField = { width: cols * QUAD, height: size + TEXT_ROWS * 2 + ambBand * 2, sceneTop: size / 2, sceneBottom: size + TEXT_ROWS * 2 + Math.min(ambBand, SCENE_OVERFLOW_ROWS) * 2 }
    const ambient = (key: string, x0: number, y0: number, columns: number, rows: number) => (
      <Raster key={key} columns={columns} rows={rows} cells={ambientCells(layers, ambField, x0, y0, columns, rows, ambT, face.mood === 'deny')} />
    )
    hdColumns = cols
    isHdSettled = isSettled(hdResize, `${cols}|${ambBand}`, frame)
    const budget = { left: HD_INLINE_MAX }
    const faceHd = hdRender('face', budget)
    const underHd = faceHd.source === null ? { source: null, toWrite: null } : hdRender('under', budget)
    for (const { toWrite, rgba } of [faceHd, underHd]) if (toWrite !== null) hdEnsure($, hdFiles, toWrite, rgba)
    const hdFace = faceHd.source
    const hdUnder = underHd.source
    const isBlink = Math.floor(frame / REFIT_FRAMES) % 2 === 0
    const moodColor = face.mood === 'idle' ? color : `#${TINT[face.mood].toString(16).padStart(6, '0')}`
    const seconds = Math.floor((frame * FRAME_MS) / 1000)
    const clock = [seconds / 3600, (seconds / 60) % 60, seconds % 60].map(n => String(Math.floor(n)).padStart(2, '0')).join(':')
    const dashes = (n: number, salt: number): string =>
      Array.from({ length: Math.max(0, n) }, (_, i) =>
        face.mood === 'deny' && noise(frame + salt, i) < 0.12 ? '╳▚░'[i % 3] : '─',
      ).join('')
    const rule = (key: string, label: string, status: string, statusColor: string, salt: number) => {
      const left = `╾─┤ ${label} ├`
      const right = ` ${status} ${isBlink ? '█' : ' '}╼`
      return (
        <Text key={key} backgroundColor="#000000" wrap="truncate">
          <Text color={color} dimColor>{'╾─┤ '}</Text>
          <Text color={color} bold>{label}</Text>
          <Text color={color} dimColor>{' ├' + dashes(cols - left.length - right.length, salt) + ' '}</Text>
          <Text color={statusColor}>{`${status} ${isBlink ? '█' : ' '}`}</Text>
          <Text color={color} dimColor>{'╼'}</Text>
        </Text>
      )
    }
    return (
      // The body's own height, so the controls can sit on its last row.
      <Box flexDirection="column" flexGrow={1} width="100%" height={e.props.scroll.bodyRows} backgroundColor="#000000">
        <Box flexDirection="row" justifyContent="center" width="100%" flexShrink={0} backgroundColor="#000000">
          {hdFace !== null && <Image key={FACE} source={hdFace} columns={cols} rows={size / 2} alt=" " />}
          {hdFace === null && ambLeft > 0 && ambient(AMB_LEFT, 0, 0, ambLeft, size / 2)}
          {hdFace === null && <Raster key={FACE} columns={size} rows={size / 2} cells={cells()} />}
          {hdFace === null && ambRight > 0 && ambient(AMB_RIGHT, ambLeft + size, 0, ambRight, size / 2)}
        </Box>
        {rule('rule-face', (who?.name ?? 'avatar7').toUpperCase(), `[${face.mood.toUpperCase()}]`, moodColor, 0)}
        <Text color={color} backgroundColor="#000000">
          {shown.length > 0 ? `> ${shown}` : '> ...'}
          {stage.typing.typed < last.text.length ? '█' : ''}
        </Text>
        {face.held !== null && (
          <Text color="#7a5cff" backgroundColor="#000000" wrap="truncate-end">
            {`waiting for a human: ${face.held}`}
          </Text>
        )}
        {stage.openQuestion !== null && (
          <Input
            key="answer"
            label="answer: "
            placeholder="ctrl+x tab, type, Enter"
            submitLabel="answer"
            autoFocus
            onSubmit={value => {
              const answer = value.replace(/\s+/g, ' ').trim().slice(0, ASKED_CHARS)
              const q = stage.openQuestion
              if (answer === '' || q === null) return
              stage.openQuestion = null
              speakLater({ question: q.text, answer })
              $.ui.invalidate('ui.render')
            }}
          />
        )}
        {isChatting && (
          <Input
            key="chat"
            label="chat: "
            placeholder="ctrl+x tab, say anything, Enter"
            submitLabel="say"
            autoFocus
            onSubmit={value => {
              const said = value.replace(/\s+/g, ' ').trim().slice(0, CONSULT_CHARS_ASKED)
              if (said === '') return
              speakLater({ chat: said })
              $.ui.invalidate('ui.render')
            }}
          />
        )}
        {isConsulting && (
          <Input
            key="consult"
            label="ask: "
            placeholder="ctrl+x tab, your question, Enter"
            submitLabel="ask"
            autoFocus
            onSubmit={value => {
              const question = value.replace(/\s+/g, ' ').trim().slice(0, CONSULT_CHARS_ASKED)
              if (question === '') return
              isConsulting = false
              speakLater({ consult: question })
              $.ui.invalidate('ui.render')
            }}
          />
        )}
        <Box flexGrow={1} height={0} overflow="hidden" flexDirection="column" justifyContent="flex-end" backgroundColor="#000000">
          {ambBand > 0 && hdUnder !== null && <Image key={AMB_BAND} source={hdUnder} columns={cols} rows={ambBand} alt=" " />}
          {ambBand > 0 && hdUnder === null && ambient(AMB_BAND, 0, size + TEXT_ROWS * 2, cols, ambBand)}
        </Box>
        {rule('rule-controls', 'CTRL', `UP ${clock}`, color, 7)}
        {isPicking && (
          <Box flexDirection="row" flexWrap="wrap" columnGap={2} backgroundColor="#000000">
            {AVATARS.map(id => (
              <Button
                key={`pick-${id}`}
                label={names[id] ?? id}
                plain
                dimColor={id !== current}
                onPress={() => {
                  if (id !== current) pendingAvatar = id
                  isPicking = false
                  $.ui.invalidate('ui.render')
                }}
              />
            ))}
          </Box>
        )}
        <Box flexDirection="row" flexWrap="wrap" columnGap={2} backgroundColor="#000000">
          <Button key="talk" label="talk" hotkey="t" plain dimColor onPress={() => speakLater('talk')} />
          <Button
            key="ask"
            label={isConsulting ? 'close ask' : 'ask'}
            hotkey="q"
            plain
            dimColor
            onPress={() => {
              isConsulting = !isConsulting
              $.ui.invalidate('ui.render')
            }}
          />
          <Button
            key="chat"
            label={isChatting ? 'close chat' : 'chat'}
            hotkey="h"
            plain
            dimColor
            onPress={() => {
              isChatting = !isChatting
              $.ui.invalidate('ui.render')
            }}
          />
          <Button
            key="avatars"
            label={isPicking ? 'close' : 'avatars'}
            hotkey="c"
            plain
            dimColor
            onPress={() => {
              isPicking = !isPicking
              $.ui.invalidate('ui.render')
            }}
          />
          <Button
            key="mute"
            label={muted ? 'unmute' : 'mute'}
            hotkey="m"
            plain
            dimColor
            onPress={() => update($, isMuted, was => !was)}
          />
          <Button
            key="events"
            label={eventsOn ? 'events: on' : 'events: off'}
            hotkey="e"
            plain
            dimColor
            onPress={async () => {
              eventsOn = !eventsOn
              await $.store.set('events', eventsOn)
              $.ui.invalidate('ui.render')
            }}
          />
          <Button
            key="visits"
            label={visitsOn ? 'visits: on' : 'visits: off'}
            hotkey="v"
            plain
            dimColor
            onPress={async () => {
              visitsOn = !visitsOn
              await $.store.set('visits', visitsOn)
              $.ui.invalidate('ui.render')
            }}
          />
          <Box flexDirection="row" gap={1} backgroundColor="#000000">
            <Text dimColor backgroundColor="#000000">vol</Text>
            <Button
              key="quieter"
              label="-"
              plain
              dimColor
              onPress={async () => {
                const v = await update($, volume, was => Math.max(0, was - VOLUME_STEP))
                await $.store.set('volume', v)
              }}
            />
            <Text dimColor backgroundColor="#000000">{String(vol)}</Text>
            <Button
              key="louder"
              label="+"
              plain
              dimColor
              onPress={async () => {
                const v = await update($, volume, was => Math.min(100, was + VOLUME_STEP))
                await $.store.set('volume', v)
              }}
            />
          </Box>
        </Box>
      </Box>
    )
  })
}

files.hooks/ambient.ts:
// Pixel weather in the black around the face: one or two layers per persona,
// read from its persona.json `ambient`. Every pixel is a function of its place
// and the ambient's own time through hashed noise, so no drop is kept; only
// the fitted scene and the current bolt are cached.

export type AmbientKind = 'rain' | 'rise' | 'wind' | 'stars' | 'bolt' | 'pulse' | 'scene' | 'grid'

// density: the share of columns, rows or pixels that carry something (0-1);
// speed: pixels a second for what moves, the twinkle's pace for stars.
// scene: a backdrop baked by tools/bake_scene.py, `file` of `width` x `height`
// pixels, its bytes attached as `pixels` when the persona loads.
export type AmbientLayer = {
  kind: AmbientKind
  color: string
  density?: number
  speed?: number
  file?: string
  width?: number
  height?: number
  pixels?: Uint8Array
  // What moves in a scene: blinking red beacons, flickering neon signs,
  // windows going dark; none when absent, the backdrop then stays still.
  animate?: ('beacons' | 'neon' | 'windows')[]
  // grid: where its horizon sits, as a share of the scene's bottom row.
  horizon?: number
}

// The field the layers draw on: the pane's width, two pixels per column, and
// the face's height plus the band under the text, two pixels per row. A cell
// is drawn as a quadrant block (2x2), so its pixels are half as wide as tall:
// QUAD of them across make one square. A scene covers the field from
// `sceneTop` down to `sceneBottom`: from the face's middle, then a few rows
// past the text.
export type Field = { width: number; height: number; sceneTop: number; sceneBottom: number }
export const QUAD = 2

// How bright the weather may get against the face: it stays behind it.
const DIM = 0.5

const hash = (a: number, b: number, c = 0): number => {
  let n = (a * 374761393 + b * 668265263 + c * 2147483647) | 0
  n = Math.imul(n ^ (n >>> 13), 1274126177)
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296
}

// Parsed once per color, not per pixel. Black stays black; `#abc` is
// `#aabbcc`; anything else unreadable is white.
const colors = new Map<string, number>()
const rgb = (hex: string): number => {
  let c = colors.get(hex)
  if (c === undefined) {
    let h = hex.replace('#', '')
    if (h.length === 3) h = [...h].map(d => d + d).join('')
    c = /^[0-9a-f]{6}$/i.test(h) ? parseInt(h, 16) : 0xffffff
    colors.set(hex, c)
  }
  return c
}

const scale = (c: number, k: number): number =>
  (Math.min(255, Math.round(((c >> 16) & 0xff) * k)) << 16) |
  (Math.min(255, Math.round(((c >> 8) & 0xff) * k)) << 8) |
  Math.min(255, Math.round((c & 0xff) * k))

// A streak running along one line, its head brightest: rain down a column,
// wind along a row. Returns the light at `at` on that line, 0 when dark.
const streak = (line: number, at: number, length: number, t: number, speed: number, trail: number, density: number, salt: number): number => {
  if (hash(line, salt) >= density) return 0
  const period = length + trail + Math.floor(hash(line, salt + 1) * length)
  const head = (t * speed * (0.7 + 0.6 * hash(line, salt + 2)) + hash(line, salt + 3) * period) % period
  const d = head - at
  return d >= 0 && d < trail ? 1 - d / trail : 0
}

// A scene fitted to the field's width, anchored to its bottom, its top fading
// into the black; each pixel sorted once so the right ones move: red lights
// on the antennas blink, neon signs flicker, windows go dark and light again.
const STILL = 0
const BEACON = 1
const NEON_SIGN = 2
const WINDOW = 3
// The backdrop stays a little under full light, behind the face.
const SCENE = 0.8
// A scene without animate: one shared empty list, not one per pixel.
const NO_MOVES: NonNullable<AmbientLayer['animate']> = []
type Scene = { width: number; height: number; rgb: Uint32Array; sort: Uint8Array }
let sceneOf: Uint8Array | null = null
let sceneWidth = 0
let scene: Scene = { width: 0, height: 0, rgb: new Uint32Array(0), sort: new Uint8Array(0) }

const fitScene = (layer: AmbientLayer, f: Field): Scene | null => {
  const px = layer.pixels
  const sw = layer.width ?? 0
  const sh = layer.height ?? 0
  const h = f.sceneBottom - f.sceneTop
  if (px === undefined || sw === 0 || sh === 0 || f.width === 0 || h <= 0) return null
  if (px === sceneOf && f.width === sceneWidth && h === scene.height) return scene
  // Cover the region, as a CSS background does: scaled until both sides fill
  // it, centered across, the ground kept and the sky cropped.
  const w = f.width
  const k = Math.max(w / QUAD / sw, h / sh)
  const left = (sw * k - w / QUAD) / 2
  const top = sh * k - h
  const rgbOut = new Uint32Array(w * h)
  const sort = new Uint8Array(w * h)
  const lums = new Float32Array(w * h)
  const lumAt = (at: number): number => lums[at] ?? 0
  for (let y = 0; y < h; y++) {
    const y0 = Math.min(sh - 1, Math.floor((y + top) / k))
    const y1 = Math.max(y0 + 1, Math.min(sh, Math.floor((y + 1 + top) / k)))
    // Faded into the black at the top, and at the bottom where it runs out
    // under the text.
    const fade = Math.min(1, y / (h * 0.2), (h - 1 - y) / (h * 0.12))
    for (let x = 0; x < w; x++) {
      const x0 = Math.min(sw - 1, Math.floor((x / QUAD + left) / k))
      const x1 = Math.max(x0 + 1, Math.min(sw, Math.floor(((x + 1) / QUAD + left) / k)))
      // The block's mean, but a beacon or a sign keeps its strongest pixel:
      // averaged, a light one pixel wide would sink into the night.
      let r = 0
      let g = 0
      let b = 0
      let best = -1
      let bestColor = 0
      let bestSort = STILL
      for (let sy = y0; sy < y1; sy++) {
        for (let sx = x0; sx < x1; sx++) {
          const i = (sy * sw + sx) * 3
          const pr = px[i] ?? 0
          const pg = px[i + 1] ?? 0
          const pb = px[i + 2] ?? 0
          r += pr
          g += pg
          b += pb
          const max = Math.max(pr, pg, pb)
          const sat = max === 0 ? 0 : (max - Math.min(pr, pg, pb)) / max
          const isBeacon = pr > 140 && pg < pr * 0.5 && pb < pr * 0.5
          const isSign = !isBeacon && sat > 0.45 && max > 150
          if ((isBeacon || isSign) && max > best) {
            best = max
            bestColor = (pr << 16) | (pg << 8) | pb
            bestSort = isBeacon ? BEACON : NEON_SIGN
          }
        }
      }
      const n = (x1 - x0) * (y1 - y0)
      const mean = ((Math.round(r / n) << 16) | (Math.round(g / n) << 8) | Math.round(b / n)) >>> 0
      const lum = (0.3 * r + 0.59 * g + 0.11 * b) / n
      const at = y * w + x
      rgbOut[at] = scale(best >= 0 ? bestColor : mean, fade)
      sort[at] = best >= 0 ? bestSort : STILL
      lums[at] = lum
    }
  }
  // A window is a point of light: brighter than the pixels around it, not a
  // lit wall or a patch of sky, which would go dark in specks.
  // A sign stands out from what is beside it; a saturated sky does not, and
  // would flicker in bars. Signs are upright strips: compare left and right.
  const SIDE = 4
  for (let y = 2; y < h - 2; y++) {
    for (let x = SIDE; x < w - SIDE; x++) {
      const at = y * w + x
      if (sort[at] !== NEON_SIGN) continue
      let beside = 0
      for (const dy of [-2, 0, 2]) beside += lumAt(at + dy * w - SIDE) + lumAt(at + dy * w + SIDE)
      if (lumAt(at) < 1.3 * (beside / 6)) sort[at] = STILL
    }
  }
  for (let y = 1; y < h - 1; y++) {
    for (let x = 1; x < w - 1; x++) {
      const at = y * w + x
      if (sort[at] !== STILL || lumAt(at) < 60) continue
      let around = 0
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) around += lumAt(at + dy * w + dx)
      if (lumAt(at) > 1.35 * ((around - lumAt(at)) / 8)) sort[at] = WINDOW
    }
  }
  sceneOf = px
  sceneWidth = w
  scene = { width: w, height: h, rgb: rgbOut, sort }
  return scene
}

// The scene's color at a field pixel, or -1 where it does not reach.
const scenePixel = (layer: AmbientLayer, f: Field, x: number, y: number, t: number): number => {
  const s = fitScene(layer, f)
  if (s === null) return -1
  const sy = y - f.sceneTop
  if (sy < 0 || sy >= s.height || x >= s.width) return -1
  const at = sy * s.width + x
  let k = SCENE
  const moves = layer.animate ?? NO_MOVES
  const sort = s.sort[at]
  if (!(sort === BEACON ? moves.includes('beacons') : sort === NEON_SIGN ? moves.includes('neon') : sort === WINDOW && moves.includes('windows'))) {
    return scale(s.rgb[at] ?? 0, k)
  }
  switch (sort) {
    case BEACON:
      k *= (t * 0.8 + hash(x >> 1, sy >> 1, 77)) % 1 < 0.6 ? 1 : 0.2
      break
    case NEON_SIGN:
      k *= hash(x >> 2, Math.floor(t * 6), 78) < 0.03 ? 0.3 : 1
      break
    case WINDOW:
      k *= hash(x, sy, Math.floor(t / 4 + hash(x, sy, 79) * 7)) < 0.15 ? 0.45 : 1
      break
  }
  return scale(s.rgb[at] ?? 0, k)
}

// A bolt strikes in a slot of 0.4 s: rarely on its own, every slot while
// `isStorm`. Its path is cached for the slot.
let boltFor = ''
let boltPath: number[] = []
const bolt = (f: Field, t: number, isStorm: boolean): number[] | null => {
  const slot = Math.floor(t / 0.4)
  if (!isStorm && hash(slot, 51) >= 0.03) return null
  if (isStorm && hash(slot, 52) >= 0.5) return null
  const id = `${slot}:${f.width}x${f.height}`
  if (id !== boltFor) {
    boltPath = []
    let x = Math.floor(hash(slot, 53) * f.width)
    for (let y = 0; y < f.height; y++) {
      x += Math.round((hash(slot, y, 54) - 0.5) * 3)
      boltPath.push(x)
    }
    boltFor = id
  }
  return boltPath
}

// One layer's light at a pixel, 0 to 1.
const light = (layer: AmbientLayer, f: Field, x: number, y: number, t: number, isStorm: boolean): number => {
  const density = layer.density
  const speed = layer.speed
  switch (layer.kind) {
    case 'rain':
      return streak(x, y, f.height, t, speed ?? 24, 6, density ?? 0.25, 1)
    case 'wind':
      return streak(y, x, f.width, t, (speed ?? 40) * QUAD, 12 * QUAD, density ?? 0.12, 11)
    case 'rise': {
      // Up a column, swaying a pixel either side, fading as it climbs.
      for (let c = x - 1; c <= x + 1; c++) {
        if (hash(c, 21) >= (density ?? 0.15)) continue
        const period = f.height + Math.floor(hash(c, 22) * f.height)
        const climbed = (t * (speed ?? 8) * (0.6 + 0.8 * hash(c, 23)) + hash(c, 24) * period) % period
        const py = Math.round(f.height - climbed)
        const px = c + Math.round(Math.sin(t * 1.7 + c) * 1)
        if (px === x && (py === y || py === y + 1)) return Math.max(0.15, py / f.height) * (py === y ? 1 : 0.5)
      }
      return 0
    }
    case 'stars': {
      if (hash(x, y, 31) >= (density ?? 0.015) / QUAD) return 0
      return 0.25 + 0.75 * (0.5 + 0.5 * Math.sin(t * (speed ?? 1) * (0.5 + hash(x, y, 32)) + hash(x, y, 33) * 6.28))
    }
    case 'bolt': {
      const path = bolt(f, t, isStorm)
      if (path === null) return 0
      const d = Math.abs((path[y] ?? -9) - x)
      return d === 0 ? 1 : d === 1 ? 0.25 : 0
    }
    case 'scene':
      // Drawn in color by scenePixel.
      return 0
    case 'grid': {
      // An outrun floor: rows closer together toward the horizon, scrolling
      // toward the viewer; rays fanning out from its middle.
      // Its horizon where the scene fades out under the text, so the floor
      // and its vanishing point fill the band below.
      const horizon = Math.round(f.sceneBottom * (layer.horizon ?? 0.92))
      if (y < horizon) return 0
      if (y === horizon) return 1
      // Perspective: a floor point at distance Z shows at depth 1/Z below the
      // horizon, and its offset across shrinks by the same depth, so the rays
      // meet at the middle of the horizon.
      const span = f.height - horizon
      const depth = (y - horizon) / span
      const next = (y - horizon + 1) / span
      // A row line lands on the pixel row whose span of Z holds it: one pixel
      // thin. Rows every ROW of Z, coming toward the viewer; toward the horizon
      // a pixel row spans more of Z, and they fade before they would merge.
      const ROW = 0.2
      const z = 1 / depth
      const zNext = 1 / next
      const shift = t * (speed ?? 1.5)
      const rowFade = Math.min(1, Math.max(0, (ROW / 2 - (z - zNext)) / (ROW / 4)))
      const row = Math.floor(z / ROW + shift) !== Math.floor(zNext / ROW + shift) ? rowFade : 0
      // Rays every SPACING squares across, as seen at the bottom row, drawn
      // soft (by distance to the line) so a slanted one does not stair-step,
      // and faded where they crowd toward the vanishing point.
      const SPACING = 8
      const gap = SPACING * depth * QUAD
      const across = (x + 0.5 - f.width / 2) / QUAD / depth / SPACING
      const off = Math.abs(across - Math.round(across)) * gap
      const ray = Math.max(0, 1 - off) * Math.min(1, Math.max(0, (gap - 3) / 6))
      const k = Math.max(row, ray)
      return k > 0 ? k * (0.35 + 0.65 * depth) : 0
    }
    case 'pulse': {
      // Wires every 9 rows, a bright pulse running along each.
      if (y % 9 !== 4) return 0
      const wire = Math.floor(y / 9)
      const at = (t * (speed ?? 30) * QUAD + hash(wire, 61) * (f.width + 20)) % (f.width + 20)
      const d = Math.abs(at - x) / QUAD
      return d < 3 ? 1 - d / 3 : 0.12
    }
  }
}

// Light added to light, each channel capped: a faint drop over a bright sky
// brightens it a little instead of punching a dark hole in it.
const add = (a: number, b: number): number =>
  (Math.min(255, ((a >> 16) & 0xff) + ((b >> 16) & 0xff)) << 16) |
  (Math.min(255, ((a >> 8) & 0xff) + ((b >> 8) & 0xff)) << 8) |
  Math.min(255, (a & 0xff) + (b & 0xff))

// The color of a field pixel: a scene lays its backdrop, the layers above
// add their light to it; black when nothing does. `isStorm` raises bolts on
// a refusal.
export const ambientPixel = (layers: AmbientLayer[], f: Field, x: number, y: number, t: number, isStorm: boolean): number => {
  let out = 0
  for (const layer of layers) {
    if (layer.kind === 'scene') {
      const c = scenePixel(layer, f, x, y, t)
      if (c >= 0) out = c
      continue
    }
    const k = light(layer, f, x, y, t, isStorm)
    if (k > 0) out = add(out, scale(rgb(layer.color), k * DIM))
  }
  return out
}

// Quadrant blocks by the mask of their lit quarters: upper left 1, upper
// right 2, lower left 4, lower right 8.
const QUADRANTS = [0x20, 0x2598, 0x259d, 0x2580, 0x2596, 0x258c, 0x259e, 0x259b, 0x2597, 0x259a, 0x2590, 0x259c, 0x2584, 0x2599, 0x259f, 0x2588]

const distance = (a: number, b: number): number =>
  Math.abs(((a >> 16) & 0xff) - ((b >> 16) & 0xff)) + Math.abs(((a >> 8) & 0xff) - ((b >> 8) & 0xff)) + Math.abs((a & 0xff) - (b & 0xff))

// The mean color of the quarters in `mask` (bit m: quarter m), 0 for none.
const meanOf = (q: readonly number[], mask: number): number => {
  let r = 0
  let g = 0
  let b = 0
  let n = 0
  for (let m = 0; m < 4; m++) {
    if ((mask & (1 << m)) === 0) continue
    const c = q[m] ?? 0
    r += (c >> 16) & 0xff
    g += (c >> 8) & 0xff
    b += c & 0xff
    n += 1
  }
  return n === 0 ? 0 : (Math.round(r / n) << 16) | (Math.round(g / n) << 8) | Math.round(b / n)
}

// A Raster's cells for the field's rectangle at column x0 and pixel row y0,
// `columns` wide and `rows` tall. Each cell holds four pixels and shows two
// colors, as chafa does: the two most different quarters lead, each other
// quarter joins the nearer one, and the glyph draws the first group.
export const ambientCells = (layers: AmbientLayer[], f: Field, x0: number, y0: number, columns: number, rows: number, t: number, isStorm: boolean): string => {
  const words = new Uint32Array(columns * rows * 3)
  const q = [0, 0, 0, 0]
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < columns; col++) {
      const i = (row * columns + col) * 3
      const x = (x0 + col) * QUAD
      const y = y0 + row * 2
      q[0] = ambientPixel(layers, f, x, y, t, isStorm)
      q[1] = ambientPixel(layers, f, x + 1, y, t, isStorm)
      q[2] = ambientPixel(layers, f, x, y + 1, t, isStorm)
      q[3] = ambientPixel(layers, f, x + 1, y + 1, t, isStorm)
      let a = 0
      let b = 1
      let far = -1
      for (let m = 0; m < 4; m++) {
        for (let n = m + 1; n < 4; n++) {
          const d = distance(q[m] ?? 0, q[n] ?? 0)
          if (d > far) {
            far = d
            a = m
            b = n
          }
        }
      }
      // Each quarter joins the nearer lead; no array per cell.
      const qa = q[a] ?? 0
      const qb = q[b] ?? 0
      let mask = 0
      for (let m = 0; m < 4; m++) {
        const c = q[m] ?? 0
        if (distance(c, qa) <= distance(c, qb)) mask |= 1 << m
      }
      words[i] = QUADRANTS[mask] ?? 0
      words[i + 1] = meanOf(q, mask)
      words[i + 2] = meanOf(q, ~mask & 0xf)
    }
  }
  return new Uint8Array(words.buffer).toBase64()
}

files.hooks/relay.ts:
// The remote voice: while tools/relay.py runs, the session that holds it sends
// its lines, its face and the page's presses through a spool, for a browser
// tab on another machine of the tailnet; every other session, and this one
// when it does not hold it, speaks on the host. Here: the protocol, the shell
// that touches the spool, the state and the decisions. The engine calls ($)
// stay in register.tsx, which the engine requires: $ is never followed across
// an import.

export const RELAY_SPOOL = '${XDG_CACHE_HOME:-$HOME/.cache}/avatar7/relay'

// The face as the relay's page draws it: who, in which mood, saying what, for
// how long; written whole to the spool when it changes, while the relay runs.
// The pane's controls ride along, so the page can draw them as they stand.
export type Mirror = {
  persona: string
  name: string
  color: string
  mood: string
  line: string
  seq: number
  speakMs: number
  isSpeaking: boolean
  question: string
  avatars: { id: string; name: string }[]
  isMuted: boolean
  eventsOn: boolean
  visitsOn: boolean
  volume: number
  // Which session holds the relay: short id, folder, last prompt typed.
  session: string
}

// What the page may ask: the pane's gestures, never mesh7's approvals. talk,
// ask and chat do reach the session: Haiku reads its last messages and the
// answer goes back to the page, which also shows 40 characters of the last
// prompt. The relay binds to the tailnet only, and takes presses only while a
// session holds it.
export type Remote =
  | { cmd: 'talk' | 'mute' | 'events' | 'visits' }
  | { cmd: 'ask' | 'answer' | 'chat'; text: string }
  | { cmd: 'avatar'; id: string }
  | { cmd: 'volume'; step: 1 | -1 }
export const parseRemote = (line: string): Remote | undefined => {
  let r: unknown
  try {
    r = JSON.parse(line)
  } catch {
    return undefined
  }
  if (typeof r !== 'object' || r === null) return undefined
  const o = r as Record<string, unknown>
  if (o.cmd === 'talk' || o.cmd === 'mute' || o.cmd === 'events' || o.cmd === 'visits') return { cmd: o.cmd }
  if ((o.cmd === 'ask' || o.cmd === 'answer' || o.cmd === 'chat') && typeof o.text === 'string') return { cmd: o.cmd, text: o.text }
  if (o.cmd === 'avatar' && typeof o.id === 'string') return { cmd: 'avatar', id: o.id }
  if (o.cmd === 'volume' && (o.step === 1 || o.step === -1)) return { cmd: 'volume', step: o.step }
  return undefined
}

// How often, in frames, the clock looks for the relay's spool, mirrors, and
// reads the page.
export const CHECK_FRAMES = 30
export const MIRROR_FRAMES = 3
export const DRAIN_FRAMES = 8

// The relay belongs to the session that ran /avatar remote on, named in its
// spool's `owner`: every other session keeps its voice and face on this machine.
// A relay that died without cleaning up (killed, crashed at start) leaves its
// spool behind: the owner holds it only while the process in relay.pid lives.
const ownsRelay = `[ "$(cat "${RELAY_SPOOL}/owner" 2>/dev/null)" = "$2" ] && kill -0 "$(cat "${RELAY_SPOOL}/relay.pid" 2>/dev/null)" 2>/dev/null`
const owned = (name: string, script: string, session: string): string[] => ['sh', '-c', script, name, '', session]
// Prints `up` while this session holds a live relay.
export const heldArgv = (session: string): string[] => owned('avatar7-relay', `${ownsRelay} && echo up`, session)
// Prints `up` while a relay process lives, whoever holds it.
export const aliveArgv = (): string[] => ['sh', '-c', `p="${RELAY_SPOOL}/relay.pid"; [ -f "$p" ] && kill -0 "$(cat "$p")" 2>/dev/null && echo up`]
// No service runs the relay: started from the plugin, detached so a reload
// does not kill it, on a clean spool.
export const startArgv = (root: string): string[] => [
  'bash',
  '-c',
  `rm -rf "${RELAY_SPOOL}"; setsid python3 "$0/tools/relay.py" </dev/null >/dev/null 2>&1 &`,
  root,
]
// Take the relay (when it runs), or give it back (when this session has it).
export const takeArgv = (session: string): string[] =>
  owned('avatar7-take', `[ -d "${RELAY_SPOOL}" ] && printf %s "$2" > "${RELAY_SPOOL}/owner"`, session)
// Given back, the page hears that nobody holds the relay rather than keeping
// the last face it saw.
export const releaseArgv = (session: string): string[] =>
  owned(
    'avatar7-release',
    `${ownsRelay} && rm -f "${RELAY_SPOOL}/owner" && printf '{}' > "${RELAY_SPOOL}/state.part" && mv "${RELAY_SPOOL}/state.part" "${RELAY_SPOOL}/state.json"; true`,
    session,
  )
export const mirrorArgv = (session: string): string[] =>
  owned('avatar7-mirror', `d="${RELAY_SPOOL}"; ${ownsRelay} && cat > "$d/state.part" && mv "$d/state.part" "$d/state.json"`, session)
// The page's buttons, queued by the relay as one JSON file each under cmd/:
// read in order and removed, one per line.
export const drainArgv = (): string[] => [
  'sh',
  '-c',
  `for f in "${RELAY_SPOOL}"/cmd/*.json; do [ -f "$f" ] && cat "$f" && echo && rm -f "$f"; done; true`,
]

// A line's WAV: to the spool when this session holds the relay (Opus for the
// trip, renamed in place so never served half written), otherwise played on
// the host by `local`, a shell command reading the WAV as $1. The WAV goes
// either way.
export const playArgv = (wav: string, session: string, local: string): string[] => [
  'bash',
  '-c',
  `d="${RELAY_SPOOL}"; if ${ownsRelay}; then n="$d/$(date +%s%N)"; ` +
    // A 16 s line: 732 KB of WAV, 67 KB of Opus, 0.3 s to encode.
    `if ffmpeg -loglevel error -nostdin -i "$1" -c:a libopus -b:a 32k -f ogg "$n.part"; then mv "$n.part" "$n.ogg"; ` +
    `else cp "$1" "$n.part" && mv "$n.part" "$n.wav"; fi; ` +
    `else ${local}; fi; rm -f "$1"`,
  'avatar7-play',
  wav,
  session,
]

// The relay as one session sees it. `session` is this session's id, '' for a
// background session, which never holds the relay.
export type Relay = {
  session: string
  isHeld: boolean
  // /avatar remote on: held whatever the next prompt's origin, until off.
  isForced: boolean
  // A session typed into over ssh: its user is elsewhere, like Remote Control's.
  isSsh: boolean
  isMirroring: boolean
  isDraining: boolean
  mirrored: string
}
export const newRelay = (): Relay => ({ session: '', isHeld: false, isForced: false, isSsh: false, isMirroring: false, isDraining: false, mirrored: '' })

// What the relay asks of avatar7: the face to show (undefined while there is
// none), and what to do with a press from the page.
export type RelayHost = {
  face: () => Promise<Mirror> | undefined
  press: (r: Remote) => Promise<void>
}

// Where a prompt sends the voice: away through the relay for one sent by
// Remote Control or typed over ssh, back here for one typed at this terminal
// (unless held by force).
export const follows = (r: Relay, origin: string): 'take' | 'give' | 'stay' =>
  r.session === '' ? 'stay' : origin === 'bridge' || (origin === 'composer' && r.isSsh) ? 'take' : origin === 'composer' && !r.isForced ? 'give' : 'stay'

// A session that ends gives the relay back: an owner gone for good would hold
// the page on its last face, and keep the others' voices off it. A /clear goes
// on in this process: a relay held by force stays held, and the next check
// hands it to the new session id.
export const givesOnEnd = (r: Relay, reason: string): boolean => r.session !== '' && !(reason === 'clear' && r.isForced)

files.hooks/memory.ts:
// A persona's memory across sessions, kept by a mem7 of its own (the
// memory_url option; empty, the personas forget as before). Each persona is a
// mem7 agent: it writes its exchanges with the user and its visits, reads its
// own memories and the shared `world`, never another persona's (the scopes of
// that mem7). At the start of a session, the persona on duty sums up what
// happened since its last journal; the journal stays, the exchanges word for
// word go after 30 days. Here: what is kept, the JSON-RPC bodies and the
// parsing. The engine calls ($) stay in register.tsx, which the engine
// requires: $ is never followed across an import.

import type { Ask } from './speech'

// The exchanges word for word, then only the journals.
export const EPISODE_TTL_S = 30 * 24 * 3600
// What a line recalls: a few exchanges matching what was said, the last
// journals whatever was said.
export const RECALL_EPISODES = 3
export const RECALL_JOURNALS = 2
// And older journals that match what was said: past two sessions, an
// exchange is gone in 30 days, and only its journal still holds it.
export const RECALL_OLD_JOURNALS = 2
// An exchange recalled is cut to this many characters, a journal to more:
// it is already the short form.
export const RECALL_CHARS = 300
export const JOURNAL_CHARS = 700
// At most this many exchanges summed up in one journal.
export const CONSOLIDATE_MAX = 40

// The identity mem7 honours on a request that carries its token.
export const META_AGENT = 'art.flux7/agent'

export type Memory = { key: string; value: string; updated: string }

// Where the persona's memory lives: the mem7 URL and the file holding its
// token (MEM7_TOKEN=...). The token goes to curl through a file descriptor,
// never on the command line, where ps would show it.
export type MemoryAt = { url: string; envFile: string }

export const memoryAt = (options: Record<string, unknown>): MemoryAt | null => {
  const url = typeof options.memory_url === 'string' ? options.memory_url.trim().replace(/\/+$/, '') : ''
  const env = typeof options.memory_env === 'string' ? options.memory_env.trim() : ''
  return url === '' ? null : { url, envFile: env }
}

// The argv that posts one JSON-RPC body (on stdin) to mem7's /rpc.
export const rpcArgv = (at: MemoryAt): string[] => [
  'bash',
  '-c',
  'f=$1; case $f in "~/"*) f=$HOME/${f#"~/"};; esac; tok=$( [ -r "$f" ] && sed -n "s/^MEM7_TOKEN=//p" "$f" ); ' +
    'curl -sS -m 5 -H @<(printf "Authorization: Bearer %s\\n" "$tok") -H "Content-Type: application/json" --data-binary @- "$2/rpc"',
  'avatar7-mem7',
  at.envFile,
  at.url,
]

const call = (agent: string, name: string, args: Record<string, unknown>): string =>
  JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args, _meta: { [META_AGENT]: agent } } })

export const storeBody = (agent: string, key: string, value: string, tags: string[], ttl = 0): string =>
  call(agent, 'memory_store', { key, value, tags, ...(ttl > 0 ? { ttl } : {}) })

// Search in plain words over the persona's memories (mem7 scopes the reads).
export const contextBody = (agent: string, query: string, tags: string[], limit: number): string =>
  call(agent, 'memory_context', { query, mode: 'natural', tags, limit })

// The most recent memories with these tags, whatever their words.
export const recallBody = (agent: string, tags: string[], limit: number): string =>
  call(agent, 'memory_recall', { tags, limit })

// The text of a tools/call answer, or '' for an error or anything else.
const resultText = (stdout: string): string => {
  try {
    const r = JSON.parse(stdout) as { result?: { content?: { text?: string }[]; isError?: boolean } }
    if (r.result === undefined || r.result.isError === true) return ''
    return r.result.content?.[0]?.text ?? ''
  } catch {
    return ''
  }
}

// memory_context answers a JSON array inside the text.
export const parseContext = (stdout: string): Memory[] => {
  try {
    const rows = JSON.parse(resultText(stdout)) as { key?: unknown; value?: unknown; updated?: unknown }[]
    if (!Array.isArray(rows)) return []
    return rows.flatMap(r =>
      typeof r.key === 'string' && typeof r.value === 'string' ? [{ key: r.key, value: r.value, updated: typeof r.updated === 'string' ? r.updated : '' }] : [],
    )
  } catch {
    return []
  }
}

// memory_recall answers markdown: "## key", the value (lines and all), then
// "Tags:", "Agent:", "Updated:" lines. Most recent first.
export const parseRecall = (stdout: string): Memory[] => {
  const text = resultText(stdout)
  if (!text.startsWith('## ')) return []
  return text
    .split(/^## /m)
    .filter(Boolean)
    .flatMap(block => {
      const nl = block.indexOf('\n')
      const key = block.slice(0, nl).trim()
      const rest = block.slice(nl + 1)
      const tags = rest.search(/\nTags: [^\n]*\n(Agent: [^\n]*\n)?Updated: /)
      if (nl < 0 || tags < 0) return []
      const updated = /\nUpdated: (\S+)/.exec(rest.slice(tags))?.[1] ?? ''
      return [{ key, value: rest.slice(0, tags), updated }]
    })
}

// The lines that recall: those that answer the user or speak of the session,
// and the opening of a visit. A tool's verdict stays immediate.
export const recalls = (ask: Ask): boolean => {
  if (ask === 'talk' || ask === 'question') return true
  if ('duo' in ask) return ask.turn <= 1
  return 'chat' in ask || 'answer' in ask || 'consult' in ask
}

// What the recall searches for: what the user said, else the visitor, else
// the last prompt typed.
export const queryFor = (ask: Ask, asked: string, other: string): string => {
  if (typeof ask === 'object') {
    if ('chat' in ask) return ask.chat
    if ('consult' in ask) return ask.consult
    if ('answer' in ask) return `${ask.question} ${ask.answer}`
    if ('duo' in ask) return other
  }
  return asked
}

// What the model reads of the past, after the prompt; '' when nothing came back.
// The journals a line reads: the last ones and the older ones that matched,
// each once, most recent first.
export const journalsFor = (latest: Memory[], matched: Memory[]): Memory[] => {
  const seen = new Set(latest.map(j => j.key))
  return [...latest, ...matched.filter(j => !seen.has(j.key)).slice(0, RECALL_OLD_JOURNALS)].sort((a, b) => (a.updated < b.updated ? 1 : -1))
}

export const memoryNote = (journals: Memory[], episodes: Memory[]): string => {
  if (journals.length === 0 && episodes.length === 0) return ''
  const cut = (s: string, max: number): string => {
    const one = s.replace(/\s+/g, ' ').trim()
    return one.length > max ? `${one.slice(0, max)}...` : one
  }
  const parts = ['\nWhat you remember from earlier sessions (use it only if it fits; never invent more):']
  for (const j of [...journals].reverse()) parts.push(`- (${j.updated.slice(0, 10)}, your journal) ${cut(j.value, JOURNAL_CHARS)}`)
  for (const e of episodes) parts.push(`- (${e.updated.slice(0, 10)}) ${cut(e.value, RECALL_CHARS)}`)
  return parts.join('\n')
}

// The exchange kept for a line, or null when the line keeps none: the user's
// words and the persona's answer, as they were said.
export const episodeOf = (ask: Ask, name: string, text: string): { value: string; kind: string } | null => {
  if (typeof ask !== 'object' || text === '') return null
  if ('chat' in ask) return { value: `User: ${ask.chat}\n${name}: ${text}`, kind: 'chat' }
  if ('consult' in ask) return { value: `User asked your opinion: ${ask.consult}\n${name}: ${text}`, kind: 'consult' }
  if ('answer' in ask) return { value: `${name} asked: ${ask.question}\nUser: ${ask.answer}\n${name}: ${text}`, kind: 'answer' }
  return null
}

// A visit, kept whole by each of the two at its last line, each in its own memory.
export const visitOf = (history: string[], last: string, other: string): string => `Visit with ${other}:\n${[...history, last].join('\n')}`

// Keys sort by time; the milliseconds keep two lines of one second apart.
const stamp = (at: Date): string => at.toISOString().replace(/[-:]/g, '').replace('.', '')
export const episodeKey = (agent: string, at: Date): string => `${agent}.ep.${stamp(at)}`
export const journalKey = (agent: string, at: Date): string => `${agent}.journal.${stamp(at)}`

// The exchanges not yet summed up: newer than the last journal, oldest first.
export const unsummed = (episodes: Memory[], journals: Memory[]): Memory[] => {
  const since = journals.reduce((m, j) => (j.updated > m ? j.updated : m), '')
  return episodes
    .filter(e => e.updated > since)
    .sort((a, b) => (a.updated < b.updated ? -1 : 1))
    .slice(-CONSOLIDATE_MAX)
}

// The model's answer when there is nothing to keep.
export const NOTHING = 'NOTHING'

export const journalPrompt = (episodes: Memory[], user: string): string =>
  `Here are your exchanges since your last journal, oldest first:\n` +
  episodes.map(e => `(${e.updated.slice(0, 10)}) ${e.value}`).join('\n\n') +
  `\n\nWrite your journal entry: two or three sentences, first person, in English, on what you learned about ${user} ` +
  `and what happened between you and the others. Keep what would matter next time; drop the small talk. ` +
  `Never write about money, family or health, even if they came up. If nothing is worth keeping, answer only ${NOTHING}.`

export const journalFrom = (r: { isAnswered: true; text: string } | { isAnswered: false }): string | null => {
  if (!r.isAnswered) return null
  const text = r.text.replace(/\s+/g, ' ').trim()
  return text === '' || text.startsWith(NOTHING) ? null : text
}

files.hooks/speech.ts:
// What the avatar says and when: the kinds of line (Ask), the queue that
// orders them, the persona's text, and how a line is asked of the model and
// kept. Pure: register.tsx reads the session, calls the model and plays the
// voice, since the engine follows $ into nothing imported.

import type { AmbientLayer } from './ambient'
import type { Mood } from './mood'

// Rules every persona keeps, whatever its character: added to each prompt.
export const STYLE = ' The user may write in French; you always answer in English. Never flattering. No quotes, no emoji, no em dash.'

// When poked, the avatar reads the last messages of the conversation, each cut
// to this many characters.
export const TALK_MESSAGES = 6
export const TALK_CHARS = 300
// Asked for an opinion, it reads further back and may say more.
export const CONSULT_MESSAGES = 12
export const CONSULT_CHARS = 600
export const CONSULT_CHARS_ASKED = 400
// A chat remembers its last six exchanges, per persona.
export const CHAT_LINES = 12

// The avatar's last lines, given back to the model so it does not repeat
// its own wording over a long session.
export const RECENT_LINES = 3

export const recentNote = (lines: string[]): string =>
  lines.length === 0 ? '' : `\nYour last lines, do not reuse their wording or openings:\n${lines.map(l => `- ${l}`).join('\n')}`

// A line to speak: an event in a mood, or the user's poke, which reads the
// conversation first; or, now and then, a moment of the persona's own story,
// a question it puts to the user, and its reaction to the user's answer.
export type Ask =
  | { mood: Mood; event: string; tool?: string; after?: number }
  | 'talk'
  | { story: string; mood: Mood }
  | 'question'
  | { question: string; answer: string }
  | { consult: string }
  | { chat: string }
  | Duo
  | { greet: string }

// One turn of a dialogue with a visiting persona: even turns are the host's,
// odd ones the guest's; `history` holds the lines said so far, by name.
export type Duo = { duo: string; turn: number; topic: 'session' | 'stories'; history: string[] }
export const DUO_TURNS = 6

// A guest for the persona on duty: any other avatar, its `friends` three
// times as likely as the rest, picked by `roll` in [0, 1).
export const FRIEND_WEIGHT = 3

export const pickGuest = (avatars: string[], current: string, roll: number, friends: string[] = []): string | undefined => {
  const others = avatars.filter(a => a !== current)
  const weights = others.map(a => (friends.includes(a) ? FRIEND_WEIGHT : 1))
  let left = roll * weights.reduce((sum, w) => sum + w, 0)
  for (const [i, a] of others.entries()) {
    left -= weights[i] ?? 1
    if (left < 0) return a
  }
  return others.at(-1)
}

export type Story = { story: string; mood: Exclude<Mood, 'idle'> }

// The persona's own lines for when the model gives none. A question or a
// dialogue turn has none: it is simply not said. The string asks are tested
// first, since `in` on a string throws (it once silenced every poke).
export const fallbackPool = (ask: Ask, fallback: Persona['fallback']): string[] => {
  if (ask === 'talk') return fallback.idle
  if (ask === 'question') return []
  if ('duo' in ask) return []
  if ('story' in ask || 'answer' in ask || 'greet' in ask) return fallback.idle
  // A stock line is no answer to a question: better silent.
  if ('consult' in ask || 'chat' in ask) return []
  return ask.mood === 'wait' ? (fallback.wait ?? fallback.watch) : fallback[ask.mood as Exclude<Mood, 'idle' | 'wait'>]
}

// One of the persona's own events, or undefined when it has none: a story
// or a question, even odds when it has both. `roll` and `pick` are in [0, 1).
export const pickEvent = (stories: Story[], canAsk: boolean, roll: number, pick: number): Ask | undefined => {
  const story = stories[Math.floor(pick * stories.length)]
  if (story !== undefined && (!canAsk || roll < 0.5)) return { story: story.story, mood: story.mood }
  return canAsk ? 'question' : undefined
}

// Rare: one event every 20 to 40 minutes, and only after a minute of quiet.
export const EVENT_MIN_FRAMES = (20 * 60_000) / 66
export const EVENT_SPAN_FRAMES = (20 * 60_000) / 66
export const EVENT_QUIET_FRAMES = 60_000 / 66
// A question unanswered for five minutes goes away.
export const QUESTION_FRAMES = (5 * 60_000) / 66

// The lines waiting for the voice, most urgent first: the user's poke, a
// refusal, a failure or a wait, then calm news; among equals the oldest. Full,
// the least urgent goes; a line that waited too long is dropped unspoken.
export type Queued = { ask: Ask; rank: number; at: number }
export const QUEUE_MAX = 4
// ~20 s of frames: past that, a line speaks of something already gone.
export const STALE_FRAMES = 300

// The persona's own events come last; the user's poke and answer first.
export const rankOf = (ask: Ask): number => {
  if (ask === 'talk') return 4
  if (ask === 'question') return 0
  if ('duo' in ask) return 0
  if ('answer' in ask || 'greet' in ask || 'consult' in ask || 'chat' in ask) return 4
  if ('story' in ask) return 0
  return ask.mood === 'deny' ? 3 : ask.mood === 'error' || ask.mood === 'wait' ? 2 : 1
}

export const enqueue = (queue: Queued[], ask: Ask, at: number): Queued[] =>
  [...queue, { ask, rank: rankOf(ask), at }].sort((a, b) => b.rank - a.rank || a.at - b.at).slice(0, QUEUE_MAX)

export const fresh = (queue: Queued[], now: number): Queued[] =>
  queue.filter(
    q =>
      q.ask === 'talk' ||
      (typeof q.ask === 'object' && ('answer' in q.ask || 'greet' in q.ask || 'consult' in q.ask || 'chat' in q.ask)) ||
      now - q.at <= STALE_FRAMES,
  )

export type Persona = {
  name: string
  voice: string
  rate: number
  pitch?: number
  // Piper voice name and pace (length-scale, under 1 is faster).
  // fx: an ffmpeg audio filter run on the WAV, from aresample=22050 so pitch
  // shifts by asetrate hold whatever the voice's own rate.
  // speaker: for a multi-speaker model, the speaker's id (speaker_id_map).
  piper?: { voice: string; lengthScale?: number; fx?: string; speaker?: number }
  color: string
  eyes: { x: number; y: number; rx: number; ry: number }[]
  mouth: { x: number; y: number; half: number } | null
  greeting: string
  persona: string
  fallback: Record<Exclude<Mood, 'wait'>, string[]> & { wait?: string[] }
  nobody?: string
  // The artists this persona would put on; jukebox7 plays them.
  station?: string[]
  // Moments of its own story it lives now and then, and the bent of the
  // questions it asks the user; either may be absent.
  events?: Story[]
  asks?: string
  // The avatars it gets on with, or against: they visit it more often.
  friends?: string[]
  // Pixel weather in the black around the face (hooks/ambient.ts).
  ambient?: AmbientLayer[]
  // The portrait's luminance (0-255) under which the scene shows through it;
  // lower for a face with dark hair, which would otherwise turn see-through.
  cutout?: number
}

// `{, user}` in a persona's text becomes ", <name>": the user_name option,
// else the persona's `nobody`, else nothing (the braces and their text drop).
export const personalize = (text: string, name: string, nobody: string | undefined): string =>
  text.replace(/\{([^{}]*)user([^{}]*)\}/g, (_, before: string, after: string) => {
    const who = name !== '' ? name : (nobody ?? '')
    return who === '' ? '' : `${before}${who}${after}`
  })


// What a line reads before it is written: how many of the session's last
// messages, each cut to how many characters; null when it reads none.
export const reads = (ask: Ask): { count: number; chars: number } | null => {
  if (ask === 'talk' || ask === 'question') return { count: TALK_MESSAGES, chars: TALK_CHARS }
  if ('consult' in ask) return { count: CONSULT_MESSAGES, chars: CONSULT_CHARS }
  if ('duo' in ask && ask.turn === 0 && ask.topic === 'session') return { count: TALK_MESSAGES, chars: TALK_CHARS }
  return null
}

// An opinion (a consult, a chat) keeps all its sentences and gets more tokens.
export const isOpinion = (ask: Ask): boolean => typeof ask === 'object' && ('consult' in ask || 'chat' in ask)

export type Asking = {
  voice: Persona
  // In a dialogue, the one spoken to.
  other: string
  // The session's last messages, as reads() asked; '' when none.
  conversation: string
  // This persona's chat with the user so far, for a chat.
  chatPast: string[]
  // What the user asked in this turn, judged against.
  asked: string
  // The avatar's own last lines, not to repeat.
  recent: string[]
}

// The prompt for a line, or null for a greeting, spoken as written.
export const promptFor = (ask: Ask, c: Asking): string | null => {
  let prompt: string
  if (ask === 'talk') {
    prompt = `The user pokes you and wants your take on where the conversation stands.\nLast messages, oldest first:\n${c.conversation}`
  } else if (ask === 'question') {
    prompt =
      `Ask the user ONE short question, then stop: philosophical, from your own story, or technical, ` +
      `about the work in the conversation below. Your bent: ${c.voice.asks ?? 'what your character would wonder'}.\n` +
      `Last messages, oldest first:\n${c.conversation}`
  } else if ('story' in ask) {
    prompt = `A moment of your own story happens now, unrelated to the tool calls: ${ask.story}. Say what you live or feel in it.`
  } else if ('duo' in ask) {
    const about =
      ask.topic === 'session' ? `the work going on in this terminal session. Last messages, oldest first:\n${c.conversation}` : 'where your two stories cross'
    prompt =
      ask.turn === 0
        ? `${c.other} visits your terminal. Open a short exchange with them, speaking to them directly, about ${about}`
        : `You are talking with ${c.other}. The exchange so far:\n${ask.history.join('\n')}\n` +
          (ask.turn === DUO_TURNS - 1 ? 'Close the exchange in one sentence, to them.' : 'Answer them in one sentence.')
  } else if ('consult' in ask) {
    prompt =
      `The user is working with an AI assistant in this terminal session and asks your opinion on it.\n` +
      `Last messages, oldest first:\n${c.conversation}\n` +
      `The user asks you: ${ask.consult}\n` +
      `Answer in character, in two or three sentences: take a position, name what you would change or keep. ` +
      `You may end on one question back.`
  } else if ('chat' in ask) {
    prompt =
      `The user talks to you personally, about whatever they like, not about the terminal session. ` +
      `This time you may use two or three sentences instead of one.\n` +
      (c.chatPast.length > 0 ? `Your conversation so far, oldest first:\n${c.chatPast.join('\n')}\n` : '') +
      `The user says: ${ask.chat}\n` +
      `Answer in character, from your own world and what you know of the user; you may ask one question back.`
  } else if ('answer' in ask) {
    prompt = `You asked the user: ${ask.question}\nThe user answered: ${ask.answer}\nReact in character: challenge it, approve it your way, or ask one follow-up.`
  } else if ('greet' in ask) {
    return null
  } else {
    prompt = c.asked === '' ? `Event: ${ask.event}` : `The user asked: ${c.asked}\nEvent: ${ask.event}`
  }
  return prompt + recentNote(c.recent)
}

// The line kept from the model's answer: an opinion whole, any other line its
// first; with no answer, one of the persona's stock lines (`roll` picks it),
// or '' where none fits.
export const lineFrom = (r: { isAnswered: true; text: string } | { isAnswered: false }, ask: Ask, voice: Persona, roll: number, userName: string): string => {
  if (r.isAnswered) return isOpinion(ask) ? r.text.replace(/\s+/g, ' ').trim() : (r.text.trim().split('\n')[0] ?? '')
  const pool = fallbackPool(ask, voice.fallback)
  return personalize(pool[roll % pool.length] ?? '', userName, voice.nobody)
}

files.hooks/hearing.ts:
// What the avatar hears besides tool calls: the slash commands that change
// the session, the other mods' announce and say, and the run of like
// outcomes the calls make. Pure.

import type { Announce, Say } from '../types'
import type { Mood } from './mood'

// How much of the user's last prompt the avatar reads, so it judges a call
// against what was asked rather than the bare gesture.
export const ASKED_CHARS = 200

// The slash commands the avatar reacts to, each with what it means: those
// that change the session or mark a moment. Any other (a look at /context,
// /mcp, a mod's own pane) passes in silence. A manual /compact is heard here;
// an automatic one through session.compact.
export const COMMANDS: Record<string, { mood: Exclude<Mood, 'idle'>; means: string }> = {
  clear: { mood: 'watch', means: 'wipes the whole conversation and starts over; say farewell to what is gone' },
  compact: { mood: 'watch', means: 'compacts the conversation: the assistant keeps a summary and forgets the rest' },
  fast: { mood: 'watch', means: 'toggles fast mode for the assistant' },
  rewind: { mood: 'error', means: 'rewinds the conversation to undo what went wrong' },
  resume: { mood: 'watch', means: 'resumes an older session' },
  brief: { mood: 'watch', means: 'asks for the morning brief: weather, mail, news; the day starts' },
  veille: { mood: 'watch', means: 'publishes the AI and streaming watch to the team Discord' },
  document: { mood: 'watch', means: 'publishes a working document as a page' },
  galerie: { mood: 'watch', means: 'publishes the latest image renders as a gallery' },
  'mesh-approve': { mood: 'wait', means: 'decides the approvals mesh7 holds for a human' },
  'code-review': { mood: 'watch', means: 'puts the code under review' },
  'security-review': { mood: 'watch', means: 'puts the code under a security review' },
  code7: { mood: 'watch', means: 'takes the keyboard back: the user writes the code, the assistant only teaches' },
}

// The line a command earns, or undefined when it passes in silence.
export const commandEvent = (command: string, args: string): { mood: Exclude<Mood, 'idle'>; event: string } | undefined => {
  const known = COMMANDS[command]
  if (known === undefined) return undefined
  const typed = args.replace(/\s+/g, ' ').trim().slice(0, ASKED_CHARS)
  return { mood: known.mood, event: `the user runs /${command}${typed === '' ? '' : ` ${typed}`}, which ${known.means}` }
}

// Whether a write landed. The host answers a plain write without `isSet`
// (2.1.288, despite StateSetResult): only a write another one beat says false.
export const landed = (done: unknown): boolean => (done as { isSet?: boolean } | undefined)?.isSet !== false

// A write another mod made, as an announce the avatar keeps, or undefined:
// its own key `announce`, a calm or amber face, and the event in words.
export const heard = (w: { plugin: string; key: string; value: unknown }): Announce | undefined => {
  if (w.key !== 'announce' || w.plugin === 'avatar7') return undefined
  const a = w.value as Partial<Announce> | undefined
  return a !== undefined && (a.mood === 'watch' || a.mood === 'error') && typeof a.event === 'string'
    ? { mood: a.mood, event: a.event }
    : undefined
}

// A `say` another mod published: speak it now, no toast needed.
export const heardSay = (w: { plugin: string; key: string; value: unknown }): Say | undefined => {
  if (w.key !== 'say' || w.plugin === 'avatar7') return undefined
  const a = w.value as Partial<Say> | undefined
  return a !== undefined &&
    (a.mood === 'watch' || a.mood === 'error' || a.mood === 'deny' || a.mood === 'wait') &&
    typeof a.event === 'string' &&
    typeof a.at === 'number'
    ? {
        mood: a.mood,
        event: a.event,
        at: a.at,
        ...(typeof a.tool === 'string' ? { tool: a.tool } : {}),
        ...(a.hold === true ? { hold: true } : {}),
        ...(a.release === true ? { release: true } : {}),
      }
    : undefined
}

// The run of like outcomes the last calls made: a third denial in a row, or
// a success after a string of failures, is news the line should carry.
export type Streak = { mood: 'watch' | 'deny' | 'error'; count: number }

export const nextStreak = (s: Streak, now: Streak['mood']): Streak =>
  s.mood === now ? { mood: now, count: s.count + 1 } : { mood: now, count: 1 }

export const ordinal = (n: number): string =>
  `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : (['th', 'st', 'nd', 'rd'][n % 10] ?? 'th')}`

export const streakNote = (before: Streak, after: Streak): string => {
  const what = (m: Streak['mood'], n: number) => (m === 'deny' ? 'denial' : 'failure') + (n > 1 ? 's' : '')
  if (after.mood !== 'watch' && after.count >= 2) return ` (${ordinal(after.count)} ${what(after.mood, 1)} in a row)`
  if (after.mood === 'watch' && before.mood !== 'watch' && before.count >= 3) {
    return ` (first success after ${before.count} ${what(before.mood, before.count)} in a row)`
  }
  return ''
}

files.hooks/voice.ts:
// The voice: a line synthesized by Piper (or spoken by SAPI when Piper is
// missing), and a WAV played on the host. Pure: argv only; register.tsx runs
// them, since the engine follows $ into nothing imported.

import type { Persona } from './speech'

export const POWERSHELL = '/mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe'
// A persona with a `pitch` (-10 to 10) speaks through the SAPI COM voice,
// which takes the pitch as XML; the text is escaped for it.
export const speakScript = (who: { voice: string; rate: number; pitch?: number }, vol: number) =>
  '[Console]::InputEncoding=[Text.Encoding]::UTF8; $t=[Console]::In.ReadToEnd(); ' +
  (who.pitch === undefined
    ? 'Add-Type -AssemblyName System.Speech; $s=New-Object System.Speech.Synthesis.SpeechSynthesizer; ' +
      `$s.SelectVoice("${who.voice}"); $s.Rate=${who.rate}; $s.Volume=${vol}; $s.Speak($t)`
    : '$q=[char]34; $v=New-Object -ComObject SAPI.SpVoice; ' +
      `$v.Voice=($v.GetVoices() | ? { $_.GetDescription() -like "${who.voice}*" } | select -First 1); ` +
      `$v.Rate=${who.rate}; $v.Volume=${vol}; ` +
      `[void]$v.Speak("<pitch absmiddle=" + $q + "${who.pitch}" + $q + ">" + [Security.SecurityElement]::Escape($t) + "</pitch>", 8)`)

// A persona with a `piper` voice speaks through Piper (local neural TTS, on
// the CPU, in WSL), its WAV played by Windows through SAPI; SAPI stays the voice
// when Piper or the model is missing. Piper lives in ~/.local/share/piper:
// .venv with piper-tts, voices/<name>.onnx. A private voice at
// custom/<avatar id>.onnx wins over the persona's (its own pace, no filter
// unless custom/<id>.fx holds one): voices one keeps out of the repo.
// Synthesis and playback are two runs so the line can be typed with the voice:
// this one prints the WAV's path and its length in seconds, or speaks through
// SAPI itself and prints nothing when Piper is missing.
export const PIPER = '$HOME/.local/share/piper'
export const synthArgv = (id: string, who: Persona, vol: number): string[] => [
  'bash',
  '-c',
  [
    't=$(cat)',
    `m="${PIPER}/voices/$1.onnx"`,
    `c="${PIPER}/custom/$6"`,
    'if [ -n "$6" ] && [ -f "$c.onnx" ]; then m="$c.onnx"; set -- "$c" "$2" 1 "$4" "$(cat "$c.fx" 2>/dev/null)" "$6" ""; fi',
    `if [ -n "$1" ] && [ -f "$m" ] && [ -x "${PIPER}/.venv/bin/python" ]; then`,
    '  w=$(mktemp --suffix=.wav); f=""; keep=""',
    // Every temporary goes on exit, but the WAV handed to the player.
    '  trap \'[ -n "$keep" ] || rm -f "$w"; rm -f "$f"\' EXIT',
    // With ffmpeg the user's volume is applied after the leveling below.
    '  v="$2"; command -v ffmpeg >/dev/null && v=1',
    // $7: a speaker of a multi-speaker model (vctk, libritts_r), by its id.
    // A Piper that fails speaks through SAPI, as a missing one does.
    `  printf %s "$t" | "${PIPER}/.venv/bin/python" -m piper -m "$m" \${7:+-s "$7"} -f "$w" --volume "$v" --length-scale "$3" 2>/dev/null || { printf %s "$t" | "${POWERSHELL}" -NoProfile -Command "$4"; exit 0; }`,
    // The persona's ffmpeg filter (pitch, metal, glitch), skipped without ffmpeg.
    '  if [ -n "$5" ] && command -v ffmpeg >/dev/null; then',
    '    f=$(mktemp --suffix=.wav)',
    '    ffmpeg -loglevel error -y -i "$w" -af "$5" "$f" && mv "$f" "$w"',
    '  fi',
    // Every voice leveled to the same loudness, then the user's volume.
    '  if command -v ffmpeg >/dev/null; then',
    '    f=$(mktemp --suffix=.wav)',
    '    ffmpeg -loglevel error -y -i "$w" -af "loudnorm=I=-18:TP=-2:LRA=11,aresample=22050,volume=$2" "$f" && mv "$f" "$w"',
    '  fi',
    `  "${PIPER}/.venv/bin/python" -c 'import sys, wave; w = wave.open(sys.argv[1]); print(sys.argv[1]); print(w.getnframes() / w.getframerate())' "$w" && keep=1`,
    'else',
    `  printf %s "$t" | "${POWERSHELL}" -NoProfile -Command "$4"`,
    'fi',
  ].join('\n'),
  'avatar7-speak',
  who.piper?.voice ?? '',
  String(Math.max(0, Math.min(100, vol)) / 100),
  String(who.piper?.lengthScale ?? 1),
  speakScript(who, vol),
  who.piper?.fx ?? '',
  id,
  who.piper?.speaker === undefined ? '' : String(who.piper.speaker),
]

// SAPI plays the WAV on the host: SoundPlayer on a \\wsl.localhost path can
// fall silent (returns at once, no error) while SAPI still reads it. The
// relay, when this session holds it, takes the WAV instead (relay.ts).
export const SAPI_PLAY = `"${POWERSHELL}" -NoProfile -Command "\\$v=New-Object -ComObject SAPI.SpVoice; \\$s=New-Object -ComObject SAPI.SpFileStream; \\$s.Open('$(wslpath -w "$1")'); [void]\\$v.SpeakStream(\\$s); \\$s.Close()"`

// How long PowerShell takes to start a detached playback, at most (measured
// ~0.3 s warm, more cold): the voice is held this much past the WAV's length.
export const PLAY_START_MS = 900

// A command run in its own session: the engine kills a module's children on
// reload, and a line half spoken was cut with them.
export const detachedArgv = (argv: string[]): string[] => ['bash', '-c', 'setsid "$0" "$@" </dev/null >/dev/null 2>&1 &', ...argv]

