// The line under the face: its text, how far it is typed, at what pace, and
// the voice that carries it. Pure: the frame clock and the speaking timer in
// register.tsx move it only through the transitions below.

export type Typing = {
  text: string
  // Characters shown, fractional: the pace adds a share of one per frame.
  typed: number
  // Characters per frame, and the frame typing starts at.
  rate: number
  from: number
  // Which line this is: a voice that comes back late types only its own.
  seq: number
  // Until when the voice is heard, in frames: the mouth moves meanwhile.
  speakUntil: number
  // One line at a time: set while a line is written, voiced and heard.
  isSpeaking: boolean
  lastSpoke: number
}

export const silent: Typing = { text: '', typed: 0, rate: 2, from: 0, seq: 0, speakUntil: 0, isSpeaking: false, lastSpoke: -Infinity }

// The line waits for its voice: typed from when SAPI starts the WAV (PowerShell
// takes ~0.3 s to get there), over the audio's length. Without a WAV within
// HOLD_FRAMES (Piper missing, SAPI speaking itself) it is typed anyway.
export const PLAY_LEAD_FRAMES = 5
export const HOLD_FRAMES = 75

// A line kept from before a reload: shown whole, nothing to type.
export const restored = (t: Typing, text: string): Typing => ({ ...t, text, typed: text.length })

// The speaking slot: taken when a line is picked from the queue, given back
// when it was heard.
export const begin = (t: Typing, now: number): Typing => ({ ...t, isSpeaking: true, lastSpoke: now })
export const end = (t: Typing): Typing => ({ ...t, isSpeaking: false })

// A new line: held until its voice is ready, unless muted.
export const start = (t: Typing, text: string, isQuiet: boolean, now: number): Typing => ({
  ...t,
  text,
  typed: 0,
  rate: 2,
  from: isQuiet ? now : now + HOLD_FRAMES,
  seq: t.seq + 1,
})

// The WAV synthArgv made (its path, then its length in seconds); the line is
// typed over the audio's length while it plays, if it is still the line on
// screen. wav is '' when SAPI already spoke it.
export const voiced = (t: Typing, seq: number, stdout: string, now: number, frameMs: number): { t: Typing; wav: string; ms: number } => {
  const [wav = '', seconds = ''] = stdout.trim().split('\n')
  const ms = Number(seconds) * 1000
  const frames = Math.round(ms / frameMs)
  if (wav === '' || !(frames > 0)) return { t, wav: '', ms: 0 }
  if (seq !== t.seq) return { t, wav, ms }
  const from = now + PLAY_LEAD_FRAMES
  return { t: { ...t, rate: Math.max(t.text.length / frames, 0.2), from, speakUntil: from + frames }, wav, ms }
}

// One frame of typing: the same object when nothing moved, so the clock
// redraws only on a change.
export const typeOn = (t: Typing, now: number): Typing =>
  t.typed < t.text.length && now >= t.from ? { ...t, typed: Math.min(t.text.length, t.typed + t.rate) } : t

export const isHeard = (t: Typing, now: number): boolean => now < t.speakUntil

files.hooks/mood.ts:
// The face's state: which mood it shows, until which frame, and the two waits
// that hold it (a call mesh7 holds for a human, a call at the permission
// prompt). Pure: every change is one of the transitions below, so the rule
// that a wait keeps the face lives here once instead of in each hook.

export type Mood = 'idle' | 'watch' | 'deny' | 'error' | 'wait'

export type Face = {
  mood: Mood
  // The frame after which the mood fades back to idle; Infinity while waiting.
  until: number
  // A call mesh7 holds for a human, as mesh7-pane said it; null when none.
  held: string | null
  heldSince: number
  // A call put to the permission prompt (a mesh7 hook's `ask`, a settings rule).
  askSince: number | null
  askCall: string
  // The mood comes from a moment of the persona's own story, not from a
  // call: the face shows it, softer (a smaller glitch on a staged refusal).
  isStaged: boolean
}

export const calm: Face = { mood: 'idle', until: 0, held: null, heldSince: 0, askSince: null, askCall: '', isStaged: false }

export const isWaiting = (f: Face): boolean => f.held !== null || f.askSince !== null

// How long a mood shows, in frames: a calm look passes faster than an alarm.
export const span = (m: Mood): number => (m === 'watch' ? 12 : 30)

// A mood for a while; a wait keeps the face as it is.
export const react = (f: Face, mood: Mood, now: number, frames = span(mood)): Face =>
  isWaiting(f) ? f : { ...f, mood, until: now + frames, isStaged: false }

// A scene of the persona's own: its mood, acted rather than suffered.
export const stage = (f: Face, mood: Mood, now: number, frames: number): Face =>
  isWaiting(f) ? f : { ...f, mood, until: now + frames, isStaged: true }

// mesh7 holds a call for a human: the face waits until the release.
export const hold = (f: Face, call: string, now: number): Face => ({ ...f, held: call, heldSince: now, mood: 'wait', until: Infinity, isStaged: false })

// The human decided: the verdict's mood, for a while.
export const release = (f: Face, mood: Mood, now: number): Face => ({ ...f, held: null, mood, until: now + 30, isStaged: false })

// A call goes to the permission prompt: the face waits until it ran.
export const ask = (f: Face, call: string, now: number): Face => ({ ...f, askSince: now, askCall: call, mood: 'wait', until: Infinity, isStaged: false })

// The call ran (or was interrupted): the prompt is gone. The mood stays until
// the call's own outcome sets it.
export const answered = (f: Face): Face => (f.askSince === null ? f : { ...f, askSince: null })

// Each frame: a wait whose end never came (mesh7-pane reloaded before its
// release, a prompt that vanished) lets go after `cap` frames; a mood past
// its time fades to idle.
export const tick = (f: Face, now: number, cap: number): Face => {
  let g = f
  if ((g.askSince !== null && now - g.askSince > cap) || (g.held !== null && now - g.heldSince > cap)) {
    g = { ...g, askSince: null, held: null, until: now }
  }
  if (now > g.until && g.mood !== 'idle') g = { ...g, mood: 'idle', isStaged: false }
  return g
}

